        fprintf(stderr, "Failed to set direction: %s\n", gpiod_error_to_msg(errno));
        gpiod_release(fd);
        return 1;
    }
    if (gpiod_set_value(fd, GPIO_LEVEL_LOW) < 0) {
        fprintf(stderr, "Failed to set value: %s\n", gpiod_error_to_msg(errno));
        gpiod_release(fd);
        return 1;
