#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/gpiod.h>

#define GPIO_FILE "/dev/gpiochip0"
#define GPIO_LINE 2

int main() {
    int fd;
    struct gpiod_line_config line_config;
    struct gpiod_line_state line_state;
    int error;

    // Initialize the GPIO device
    fd = open(GPIO_FILE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Configure the GPIO line
    line_config.line = GPIO_LINE;
    line_config.direction = GPIGPIO_OUT;
    line_config.state = 0;
    error = gpiod_line_config_set(fd, &line_config);
    if (error < 0) {
        fprintf(stderr, "Error configuring GPIO line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Initialize the GPIO line state
    line_state.value = 0;
    line_state.valid = 1;

    // Repeat once every 5 seconds
    while (1) {
        // Check if the GPIO line is valid
        if (line_state.valid == 0) {
            fprintf(stderr, "Invalid state on GPIO line %d\n", GPIO_LINE);
            continue;
        }

        // Check if the value is within the documented range
        if (line_state.value < 0 || line_state.value > 1) {
            fprintf(stderr, "Value on GPIO line %d is out of range (0-1)\n", GPIO_LINE);
            continue;
        }

        // Apply the state to the GPIO line
        error = gpiod_line_state_set(fd, &line_state);
        if (error < 0) {
            fprintf(stderr, "Error applying state to GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
            exit(EXIT_FAILURE);
        }

        // Print the state applied to standard output
        printf("State on GPIO line %d: %d\n", GPIO_LINE, line_state.value);

        // Wait for 5 seconds
        sleep(5);
    }

    // Release the GPIO device on exit
    close(fd);

    return 0;
}

