#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/i2c-gpio.h>

#define I2C_ADDR 0x48
#define ADC_ADDR 0x03

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg[2];
    int i;

    // Open the I2C bus
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set up the I2C device file descriptor
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C device file descriptor");
        exit(EXIT_FAILURE);
    }

    // Open the ADC device file descriptor
    if (open("/dev/i2c-1", O_RDWR) < 0) {
        perror("Error opening ADC device file descriptor");
        exit(EXIT_FAILURE);
    }

    // Set up the ADC device file descriptor
    if (ioctl(fd, I2C_SLAVE, ADC_ADDR) < 0) {
        perror("Error setting ADC device file descriptor");
        exit(EXIT_FAILURE);
    }

    // Initialize the ADC
    if (adc_init() < 0) {
        perror("Error initializing ADC");
        exit(EXIT_FAILURE);
    }

    // Repeat the sampling process
    while (1) {
        // Wait for 0.5 seconds
        usleep(500000);

        // Clear the screen
        system("clear");

        // Print the current ADC reading
        printf("ADC Reading: %d\n", adc_read());

        // Wait for a key press to exit
        char key;
        while ((key = getchar()) != '\n' && key != 'q');
    }

    // Release the ADC and I2C resources
    adc_release();
    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/i2c-gpio.h>

#define I2C_DEVICE_ADDRESS 0x5a
#define I2C_BUS "/dev/i2c-1"

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msgs[1];
    int rc;

    // Initialize I2C bus
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C bus speed
    if (ioctl(fd, I2C_SLAVE, I2C_DEVICE_ADDRESS) < 0) {
        perror("Failed to set I2C bus speed");
        exit(EXIT_FAILURE);
    }

    // Open the device file
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open device file");
        exit(EXIT_FAILURE);
    }

    // Set the device to non-blocking mode
    if (ioctl(fd, I2C_SLAVE, I2C_DEVICE_ADDRESS) < 0) {
        perror("Failed to set I2C device to non-blocking mode");
        exit(EXIT_FAILURE);
    }

    // Initialize the GPIO pins for I2C communication
    if (gpio_request_from_mem(GPIO_I2C_GPIO_BASE, GPIO_I2C_GPIO_SIZE, &gpio_mem) < 0) {
        perror("Failed to request GPIO pins for I2C communication");
        exit(EXIT_FAILURE);
    }

    // Set the I2C device address
    if (ioctl(fd, I2C_SLAVE, I2C_DEVICE_ADDRESS) < 0) {
        perror("Failed to set I2C device address");
        exit(EXIT_FAILURE);
    }

    // Initialize the I2C adapter
    if (i2c_adapter_init() < 0) {
        perror("Failed to initialize I2C adapter");
        exit(EXIT_FAILURE);
    }

    // Set the I2C adapter to non-blocking mode
    if (ioctl(fd, I2C_SLAVE, I2C_DEVICE_ADDRESS) < 0) {
        perror("Failed to set I2C adapter to non-blocking mode");
        exit(EXIT_FAILURE);
    }

    // Set the I2C adapter to master mode
    if (i2c_adapter_master_mode() < 0) {
        perror("Failed to set I2C adapter to master mode");
        exit(EXIT_FAILURE);
    }

    // Set the I2C adapter to use the specified GPIO pins
    if (i2c_adapter_set_io_base(fd, gpio_mem) < 0) {
        perror("Failed to set I2C adapter to use GPIO pins");
        exit(EXIT_FAILURE);
    }

    // Set the I2C device to non-blocking mode
    if (ioctl(fd, I2C_SLAVE, I2C_DEVICE_ADDRESS) < 0) {
        perror("Failed to set I2C device to non-blocking mode");
        exit(EXIT_FAILURE);
    }

    // Start the I2C adapter
    if (i2c_adapter_start(fd) < 0) {
        perror("Failed to start I2C adapter");
        exit(EXIT_FAILURE);
    }

    // Loop to read and print measurements
    while (1) {
        // Wait for the next measurement
        if (i2c_rdwr(fd, msgs, 2) < 0) {
            perror("Failed to read from I2C device");
            exit(EXIT_FAILURE);
        }

        // Check if the measurement was successful
        if (msgs[0].len != 0) {
            // Print the measurement to standard output
            printf("Measurement: %d\n", msgs[0].buf[0]);
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Release the I2C device
    if (i2c_adapter_stop(fd) < 0) {
        perror("Failed to stop I2C adapter");
        exit(EXIT_FAILURE);
    }

    // Release the GPIO pins
    gpio_release_from_mem(gpio_mem);

    // Release the I2C adapter
    i2c_adapter_exit();

    return 0;
}

