        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set up the I2C device file descriptor
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C device file descriptor");
        exit(EXIT_FAILURE);
    }

    // Open the ADC device file descriptor
    if (open("/dev/i2c-1", O_RDWR) < 0) {
        perror("Error opening ADC device file descriptor");
        exit(EXIT_FAILURE);
    }

    // Set up the ADC device file descriptor for reading
    if (ioctl(fd, I2C_RDWR, ADC_ADDR) < 0) {
