#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/gpiod.h>

int main() {
    int fd;
    struct gpiod_device *device;
    int state;

    // Initialize pigpio
    if (gpiod_init() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    // Open GPIO 18
    fd = gpiod_open(18, GPIDX_OUTPUT);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO 18\n");
        gpiod_exit();
        return 1;
    }

    // Get the device associated with GPIO 18
    device = gpiod_get_device(fd);
    if (device == NULL) {
        fprintf(stderr, "Error: Failed to get device for GPIO 18\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set the PWM state to 0 (off)
    state = 0;
    if (gpiod_set_value(device, state) < 0) {
        fprintf(stderr, "Error: Failed to set PWM state to 0\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Repeat the PWM state every 0.5 seconds
    while (1) {
        state = 1 - state;
        if (gpiod_set_value(device, state) < 0) {
            fprintf(stderr, "Error: Failed to set PWM state\n");
            break;
        }
        usleep(500000); // 0.5 seconds
    }

    // Release the GPIO
    gpiod_release(device);
    gpiod_exit();

    return 0;
}

#include <stdio.h>
