#define SENSOR_PIN 17
#define ECHO_PIN 27

int main() {
    int fd, status;
    struct gpiod_device *device;
    struct gpiod_line *line;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open the device
    fd = gpiod_open(SENSOR_PIN);
    if (fd < 0) {
        fprintf(stderr, "Failed to open device\n");
        gpiod_exit();
        return 1;
    }

    // Get the device and line
    device = gpiod_get_device(fd);
    if (device == NULL) {
        fprintf(stderr, "Failed to get device\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }
    line = gpiod_get_line(device, ECHO_PIN);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Check if the device is present
    status = gpiod_get_state(line);
    if (status < 0) {
        fprintf(stderr, "Device is absent\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Repeat every 60 seconds
    while (1) {
        // Check if the device is still present
        status = gpiod_get_state(line);
        if (status < 0) {
            fprintf(stderr, "Device is absent\n");
            gpiod_close(fd);
            gpiod_exit();
            return 1;
        }

        // Report the state
        printf("Device is present, state: %d\n", status);

        // Wait for 1 second
        sleep(1);
    }

    // Release the hardware
    gpiod_release(fd);
    gpiod_exit();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/i2c-gpio.h>

#define I2C_ADDR 0x28
#define ADC_ADDR 0x48

int main() {
    int rc;
    int i;
    int channel;
    int valid;
    int data;

    // Open the I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        return 1;
    }

    // Set the I2C address of the ADC
    struct i2c_rdwr_ioctl_data data;
    data.flags = 0;
    data.timeout_ns = 1000000000;
    data.read_write = 1;
    data.addr = I2C_ADDR;
    data.flags |= I2C_RDWR;

    // Open the ADC device file
    int adc_fd = ioctl(i2c_fd, I2C_RDWR, &data);
    if (adc_fd < 0) {
        fprintf(stderr, "Error opening ADC device file\n");
        return 1;
    }

    // Set the ADC channel
    channel = 1; // Change this to the desired channel
    data.addr = ADC_ADDR;
    data.flags = 0;
    data.read_write = 1;
    data.addr = ADC_ADDR;
    data.flags |= I2C_RDWR;
    data.reg = channel;

    // Read the ADC data
    while (1) {
        rc = ioctl(adc_fd, ADS1115_READ_REGISTER, &data);
        if (rc < 0) {
            fprintf(stderr, "Error reading ADC data\n");
            return 1;
        }

        // Validate the reading
        valid = (data.reg & 0x0F) == (channel - 1);
        if (!valid) {
            fprintf(stderr, "Invalid reading from ADC\n");
            continue;
        }

        // Print the reading
        printf("Reading: %d\n", data.reg);

        // Wait 5 seconds
        sleep(5);
    }

    // Release the ADC device file
    close(adc_fd);

    // Release the I2C bus
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/gpiod.h>

int main() {
    int fd;
    struct gpiod_device *device;
    int state;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open the device
    if ((fd = gpiod_open(GPIDO_DIR_ACTIVE, GPIDO_MODE_OUTPUT, "digital_output_18", NULL)) < 0) {
        fprintf(stderr, "Failed to open device\n");
        gpiod_exit();
        return 1;
    }

    // Get the device structure
    device = gpiod_get_device(fd);

    // Check if the device exists
    if (device == NULL) {
        fprintf(stderr, "Device absent\n");
        gpiod_exit();
        return 1;
    }

    // Set the output state to 1 (high)
    if (gpiod_set_value(device, 1) < 0) {
        fprintf(stderr, "Failed to set output state to 1\n");
        gpiod_exit();
        return 1;
    }

    // Set the output state to 0 (low) after 1 second
    if (sched_usleep(1000 * 1000) < 0) {
        fprintf(stderr, "Failed to set delay\n");
        gpiod_exit();
        return 1;
    }

    // Check the output state
    if (gpiod_get_value(device) != 0) {
        fprintf(stdout, "Output is already set to 1\n");
    }

    // Wait for interrupt
    while (1) {
        if (gpiod_interrupt_wait(device) < 0) {
            fprintf(stderr, "Failed to wait for interrupt\n");
            gpiod_exit();
            return 1;
        }
    }

    // Release the device and hardware
    gpiod_release(device);
    gpiod_exit();

    return 0;
}

