    }

    // Set the GPIO 18 to a specific state (1 for on, 0 for off)
    ret = gpiod_set(fd, GPIO18, state);
    if (ret < 0) {
        fprintf(stderr, "Error: Unable to set state\n");
        gpiod_close(fd);
        return 1;
    }

    // Loop for 3 cycles, every 2 seconds
    for (int i = 0; i < 3; i++) {
        printf("GPIO 18 state: %d\n", state);
        sleep(2);
        state = !state;
        ret = gpiod_set(fd, GPIO18, state);
        if (ret < 0) {
            fprintf(stderr, "Error: Unable to set state\n");
            break;
        }
    }

    // Release the GPIO device
    ret = gpiod_release(fd);
    if (ret < 0) {
        fprintf(stderr, "Error: Unable to release GPIO device\n");
        return 1;
    }

    return 0;
}

