    file = gpiod_open(GPIDO_DIR_TO_PATH("/dev/gpiochip0"), GPIDO_DIR_TO_PATH("/sys/class/gpio/gpio17"), GPIDO_DIR_TO_PATH("/gpio/gpio17"), GPIDO_DIR_TO_PATH("/gpio/gpiochip0"), 0);
    if (file < 0) {
        fprintf(stderr, "Failed to open device: %s\n", gpiod_error_name(file));
        gpiod_close(file);
        gpiod_exit();
        return 1;
    }

    device = gpiod_get_device(file);
    if (device == NULL) {
        fprintf(stderr, "Failed to get device: %s\n", gpiod_error_name(file));
        gpiod_close(file);
        gpiod_exit();
        return 1;
    }

