    while (1) {
        // Check if the line is still in the desired state
        if (gpiod_get_line_state(line) == state) {
            printf("Digital output is already set to %s\n", gpiod_line_direction_name(line));
            continue;
        }

        // If the line is not in the desired state, release the hardware
        if (gpiod_set_line_value(line, GPIO_ACTIVE_LOW) < 0) {
            fprintf(stderr, "Failed to set line value: %s\n", gpiod_error_name(file));
            gpiod_close(file);
            gpiod_exit();
            return 1;
        }

        // Wait for 1 second
        sleep(1);
    }

