    event_config.type = GPIDX_EVENT_GPIO;
    event_config.gpio_num = 4;
    event_config.event_type = GPIDX_EVENT_GPIO_RISING;
    event_config.event_mask = GPIDX_EVENT_GPIO_RISING;

    // Register the event configuration
    if (gpiod_event_config_register(file, &event_config) < 0) {
        fprintf(stderr, "Failed to register event configuration for GPIO line 4: %s\n", strerror(errno));
        gpiod_line_close(file);
        return 1;
    }

