    if ((fd = gpiod_open(22, GPIO_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to open GPIO 22\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }
    if ((fd = gpiod_open(27, GPIO_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to open GPIO 27\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set the initial state of the digital outputs
    state = gpiod_get_level(fd);
    if (state == 0) {
        state = 1;
    } else {
        state = 0;
    }

    // Repeat every 2 seconds
    while (1) {
        // Set the state of the digital outputs
        if (gpiod_set_level(fd, state) < 0) {
