               event.state[0], event.state[1], event.state[2], event.state[3]);

        // Wait for 2 seconds
        sleep(2);

        // Reset the state of the digital outputs
        state = gpiod_get_level(fd);
        if (state == 1) {
            state = 0;
        } else {
            state = 1;
        }

        // Set the new state of the digital outputs
        if (gpiod_set_level(fd, state) < 0) {
            fprintf(stderr, "Failed to set state on GPIO 4, GPIO 17, GPIO 22, and GPIO 27\n");
