#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/gpiod.h>

int main() {
    int fd, gpio_num;
    struct gpiod_info info;
    char state;

    // Initialize the GPIO device
    fd = gpiod_get_fd("/dev/gpiochip0");
    if (fd < 0) {
        fprintf(stderr, "Error: Unable to open GPIO device\n");
        return 1;
    }

    // Check if the device is present
    if (gpiod_get_property(fd, "name", &info.name, sizeof(info.name)) < 0) {
        fprintf(stderr, "Error: Device absent\n");
        gpiod_close(fd);
        return 1;
    }

    // Check if the GPIO number is valid
    if (info.name == NULL) {
        fprintf(stderr, "Error: Invalid GPIO number\n");
        gpiod_close(fd);
        return 1;
    }

    gpio_num = info.name - "/dev/gpiochip0";

    // Check if the GPIO number is valid
    if (gpio_num < 0 || gpio_num >= gpiod_get_num_of_gpiods()) {
        fprintf(stderr, "Error: Invalid GPIO number\n");
        gpiod_close(fd);
        return 1;
    }

    // Set the GPIO as an output
    if (gpiod_set_direction(fd, gpio_num, GPIDIO_DIR_OUT) < 0) {
        fprintf(stderr, "Error: Unable to set GPIO direction\n");
        gpiod_close(fd);
        return 1;
    }

    // Check if the GPIO is already set as an output
    if (gpiod_get_property(fd, "direction", &state, sizeof(state)) < 0) {
        fprintf(stderr, "Error: Unable to get GPIO direction\n");
        gpiod_close(fd);
        return 1;
    }

    if (state != GPIDIO_DIR_OUT) {
        fprintf(stderr, "Error: GPIO is not set as an output\n");
        gpiod_close(fd);
        return 1;
    }

    // Set the GPIO state to 1 (true)
    if (gpiod_set_value(fd, gpio_num, 1) < 0) {
        fprintf(stderr, "Error: Unable to set GPIO value\n");
        gpiod_close(fd);
        return 1;
    }

    // Repeat every 5 seconds
    while (1) {
        // Check if the GPIO state is 1 (true)
        if (gpiod_get_value(fd, gpio_num) == 1) {
            printf("GPIO %d is set to 1\n", gpio_num);
        } else {
            printf("GPIO %d is set to 0\n", gpio_num);
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Release the GPIO device
    gpiod_close(fd);

    return 0;
}

