#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/i2c-gpio.h>

#define SI7021_ADDRESS 0x40

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg[2];
    int ret;

    // Open the I2C bus
    if ((fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set the I2C address of the SI7021 sensor
    if (ioctl(fd, I2C_SLAVE, SI7021_ADDRESS) == -1) {
        perror("Error setting I2C address");
        exit(EXIT_FAILURE);
    }

    // Initialize the GPIO pins for the SI7021 sensor
    if (gpio_request_from_mem(SI7021_ADDRESS, SI7021_GPIO_PINS, 1) == -1) {
        perror("Error initializing GPIO pins");
        exit(EXIT_FAILURE);
    }

    // Initialize the I2C device
    if (i2c_init() == -1) {
        perror("Error initializing I2C device");
        exit(EXIT_FAILURE);
    }

    // Repeat once every 5 seconds
    while (1) {
        // Wait for the next measurement
        ret = i2c_rdwr_ioctl_data(fd, I2C_RDWR, &data, sizeof(data), NULL, 0);
        if (ret == -1) {
            perror("Error reading from SI7021 sensor");
            exit(EXIT_FAILURE);
        }

        // Check the validity of the reading
        if (data.status != 0x00) {
            printf("Invalid reading from SI7021 sensor\n");
            continue;
        }

        // Print the reading to standard output
        printf("SI7021 reading: %d\n", data.data);

        // Wait for 5 seconds before taking the next reading
        sleep(5);
    }

    // Release the I2C device and GPIO pins
    i2c_exit();
    gpio_release_mem(SI7021_ADDRESS, SI7021_GPIO_PINS);
    close(fd);

    return 0;
}

