int main() {
    int rc;
    int i;
    int channel = 1; // Change this to the desired channel

    // Open the I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        return 1;
    }

    // Set up the I2C device
    struct i2c_rdwr_ioctl_data data;
    data.flags = 0;
    data.timeout_ns = 1000000;
    data.sda_ioctl_function = I2C_FUNC_I2C;
    data.sda_ioctl_address = I2C_ADDR;
    data.scl_ioctl_function = I2C_FUNC_I2C;
    data.scl_ioctl_address = I2C_ADDR;

    rc = ioctl(i2c_fd, I2C_RDWR, &data);
    if (rc < 0) {
        fprintf(stderr, "Error setting up I2C device\n");
        return 1;
    }

    // Set up the ADC
    struct gpiod_adc_channel_config config;
    config.channel = channel;
    config.direction = GPIDO_ADC_DIRECTION_IN;
    config.pull_up_en = GPIDO_PULL_UP_DISABLE;
    config.pull_down_en = GPIDO_PULL_DOWN_DISABLE;
    config.sample_time = 100; // Change this to the desired sample time in microseconds

    rc = gpiod_adc_channel_config_set(i2c_fd, &config);
    if (rc < 0) {
        fprintf(stderr, "Error setting up ADC channel\n");
        return 1;
    }

    // Start the ADC conversion
    struct gpiod_adc_config adc_config;
    adc_config.channel = channel;
    adc_config.mode = GPIDO_ADC_MODE_SINGLE_SHOT;
    adc_config.sample_time = config.sample_time;
    adc_config.sample_time_us = config.sample_time;

    rc = gpiod_adc_config_set(i2c_fd, &adc_config);
    if (rc < 0) {
        fprintf(stderr, "Error setting up ADC configuration\n");
        return 1;
    }

    // Start the ADC conversion
    struct gpiod_adc_config adc_config_start;
    adc_config_start.channel = channel;
    adc_config_start.mode = GPIDO_ADC_MODE_SINGLE_SHOT;
    adc_config_start.sample_time = config.sample_time;
    adc_config_start.sample_time_us = config.sample_time;

    rc = gpiod_adc_config_set(i2c_fd, &adc_config_start);
    if (rc < 0) {
        fprintf(stderr, "Error starting ADC conversion\n");
        return 1;
    }

    // Wait for the conversion to complete
    while (1) {
        // Do nothing
    }

    // Stop the ADC conversion
    struct gpiod_adc_config adc_config_stop;
    adc_config_stop.channel = channel;
    adc_config_stop.mode = GPIDO_ADC_MODE_CONTINUOUS_SAMPLING;
    adc_config_stop.sample_time = config.sample_time;
    adc_config_stop.sample_time_us = config.sample_time;

    rc = gpiod_adc_config_set(i2c_fd, &adc_config_stop);
    if (rc < 0) {
        fprintf(stderr, "Error stopping ADC conversion\n");
        return 1;
    }

    // Release the ADC
    rc = gpiod_adc_channel_config_set(i2c_fd, &config);
    if (rc < 0) {
        fprintf(stderr, "Error releasing ADC channel\n");
        return 1;
    }

    // Close the I2C device
    rc = close(i2c_fd);
    if (rc < 0) {
        fprintf(stderr, "Error closing I2C device\n");
        return 1;
    }

    return 0;
}

