int main() {
    int fd, state;
    struct gpiod_line_config line_config;
    struct gpiod_event_config event_config;

    // Initialize GPIO
    fd = gpiod_get_default_file();
    if (fd < 0) {
        fprintf(stderr, "Failed to get default GPIO file: %s\n", strerror(errno));
        return 1;
    }

    // Set up GPIO lines
    line_config.line = GPIDO_LINE_GPIO;
    line_config.direction = GPIDO_DIRECTION_OUT;
    line_config.state = 0;
    if (gpiod_set_line(fd, GPIDO_LINE_GPIO, &line_config) < 0) {
        fprintf(stderr, "Failed to set GPIO line: %s\n", strerror(errno));
        return 1;
    }

    // Set up event configuration
    event_config.line = GPIDO_LINE_GPIO;
    event_config.event = GPIDO_EVENT_GPIO_INT;
    event_config.event_mask = GPIDO_EVENT_GPIO_INT_LOW | GPIDO_EVENT_GPIO_INT_HIGH;
    event_config.edge = GPIDO_EDGE_FALLING;
    event_config.debounce = GPIDO_DEBOUNCE_ON;
    event_config.state = 0;
    if (gpiod_set_event_config(fd, &event_config) < 0) {
        fprintf(stderr, "Failed to set event configuration: %s\n", strerror(errno));
        return 1;
    }

    // Control the GPIO lines
    for (int i = 0; i < 256; i++) {
        state = (i & 1) ? 1 : 0;
        if (gpiod_set_line(fd, GPIDO_LINE_GPIO, &line_config) < 0) {
            fprintf(stderr, "Failed to set GPIO line: %s\n", strerror(errno));
            return 1;
        }
        if (gpiod_set_line(fd, GPIDO_LINE_GPIO, &line_config) < 0) {
            fprintf(stderr, "Failed to set GPIO line: %s\n", strerror(errno));
            return 1;
        }
        if (state) {
            if (gpiod_set_line(fd, GPIDO_LINE_GPIO, &line_config) < 0) {
                fprintf(stderr, "Failed to set GPIO line: %s\n", strerror(errno));
                return 1;
            }
        } else {
            if (gpiod_clear_line(fd, GPIDO_LINE_GPIO, &line_config) < 0) {
                fprintf(stderr, "Failed to clear GPIO line: %s\n", strerror(errno));
                return 1;
            }
        }
        if (gpiod_get_line(fd, GPIDO_LINE_GPIO, &state, NULL) < 0) {
            fprintf(stderr, "Failed to get GPIO line state: %s\n", strerror(errno));
            return 1;
        }
        printf("State: %d\n", state);
    }

    // Release GPIO resources
    if (gpiod_release_line(fd, GPIDO_LINE_GPIO) < 0) {
        fprintf(stderr, "Failed to release GPIO line: %s\n", strerror(errno));
        return 1;
    }

    return 0;
}

