    fd = gpiod_open("/dev/gpiochip0", 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO device: %s\n", strerror(errno));
        return 1;
    }

    // Check if the device is a GPIO chip
    if (gpiod_chip_type(fd) != GPIDIO_CHIP_TYPE_GPIO) {
        fprintf(stderr, "Device is not a GPIO chip\n");
        return 1;
    }

