        return 1;
    }

    if (gpiod_direction_output(fd, gpio, value) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to %d: %s\n", gpio, value, strerror(errno));
        return 1;
    }

    // Print the initial state of the GPIO
    printf("Initial state of GPIO %d: %d\n", gpio, value);

    // Wait for a key press and release the GPIO
    char key;
    do {
        key = getchar();
    } while (key != '\n');

    // Release the GPIO
    if (gpiod_direction_output(fd, gpio, 0) < 0) {
