    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open GPIO 2 and GPIO 3
    fd = gpiod_get_direction(2);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO 2\n");
        gpiod_exit();
        return 1;
    }

    fd = gpiod_get_direction(3);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO 3\n");
        gpiod_exit();
        return 1;
    }

    // Set GPIO 2 and GPIO 3 to output mode
    if (gpiod_set_value(fd, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO 2 to output mode\n");
        gpiod_exit();
        return 1;
    }

    if (gpiod_set_value(fd, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO 3 to output mode\n");
        gpiod_exit();
        return 1;
    }

    // Wait for the GPIOs to be ready
    while (1) {
        if (gpiod_get_event(fd, &event) < 0) {
            fprintf(stderr, "Failed to get event from GPIO\n");
            gpiod_exit();
            return 1;
        }

        if (event.state == 1) {
            printf("GPIO 2 is now set to 1\n");
        } else {
            printf("GPIO 2 is now set to 0\n");
        }

        if (gpiod_get_event(fd, &event) < 0) {
            fprintf(stderr, "Failed to get event from GPIO\n");
            gpiod_exit();
            return 1;
        }

        if (event.state == 1) {
            printf("GPIO 3 is now set to 1\n");
        } else {
            printf("GPIO 3 is now set to 0\n");
        }

        if (gpiod_get_event(fd, &event) < 0) {
            fprintf(stderr, "Failed to get event from GPIO\n");
            gpiod_exit();
            return 1;
        }
    }

    // Release GPIO 2 and GPIO 3
    if (gpiod_set_value(fd, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO 2 to input mode\n");
        gpiod_exit();
        return 1;
    }

    if (gpiod_set_value(fd, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO 3 to input mode\n");
        gpiod_exit();
        return 1;
    }

    gpiod_exit();

    return 0;
}

