#define SENSOR_PIN 17
#define ECHO_PIN 18

int main() {
    int fd, error;
    struct gpiod_device *device;
    struct gpiod_line *line;
    int distance;

    // Initialize libgpiod
    if ((fd = gpiod_open(GPIDO_USER)) < 0) {
        fprintf(stderr, "Failed to open gpiod device\n");
        return 1;
    }

    if ((device = gpiod_get_device(fd, SENSOR_PIN)) == NULL) {
        fprintf(stderr, "Failed to get device for pin %d\n", SENSOR_PIN);
        gpiod_close(fd);
        return 1;
    }

    if ((line = gpiod_get_line(device, ECHO_PIN)) == NULL) {
        fprintf(stderr, "Failed to get line for pin %d\n", ECHO_PIN);
        gpiod_close(fd);
        gpiod_release_device(device);
        return 1;
    }

    // Set the line to input mode
    if (gpiod_line_set_input(line) < 0) {
        fprintf(stderr, "Failed to set line %d to input mode\n", ECHO_PIN);
        gpiod_close(fd);
        gpiod_release_device(device);
        return 1;
    }

    // Continuously read and print the distance
    while (1) {
        error = gpiod_line_read(line, &distance, sizeof(distance));
        if (error < 0) {
            fprintf(stderr, "Failed to read distance from pin %d: %s\n", ECHO_PIN, strerror(errno));
            gpiod_close(fd);
            gpiod_release_device(device);
            return 1;
        }

        if (distance > 0) {
            printf("Distance: %d cm\n", distance);
        }

        sleep(1);
    }

    // Release the hardware
    gpiod_close(fd);
    gpiod_release_device(device);

    return 0;
}

