#define GPIB_DEVICE_PATH "/dev/ttyUSB0"
#define BAUDRATE 9600

int main() {
    int fd;
    struct termios options;
    struct gpiob_line_config line_config;
    char buffer[256];

    // Open the serial port
    fd = open(GPIB_DEVICE_PATH, O_RDWR | O_NOCTTY);
    if (fd < 0) {
        perror("Error opening serial port");
        exit(EXIT_FAILURE);
    }

    // Set the baud rate
    tcgetattr(fd, &options);
    options.c_cflag = BAUDRATE | CS8 | CLOCAL | CREAD;
    options.c_iflag = IGNPAR;
    options.c_oflag = 0;
    options.c_lflag = 0;
    tcflush(fd, TCIFLUSH);
    tcsetattr(fd, TCSANOW, &options);

    // Configure the line for UART communication
    line_config.line_config_bits = GPIB_UART_LINE_CONFIG_BITS;
    line_config.line_config_config = GPIB_UART_LINE_CONFIG_CONFIG;
    line_config.line_config_flags = GPIB_UART_LINE_CONFIG_FLAGS;
    line_config.line_config_speed = GPIB_UART_SPEED_9600;
    line_config.line_config_parity = GPIB_UART_PARITY_NONE;
    line_config.line_config_stop_bits = GPIB_UART_STOP_BITS_1;

    if (ioctl(fd, GPIB_SET_LINE_CONFIG, &line_config) < 0) {
        perror("Error setting UART line configuration");
        exit(EXIT_FAILURE);
    }

    // Wait for the device to be present
    while (1) {
        if (read(fd, buffer, sizeof(buffer)) < 0) {
            perror("Error reading from serial port");
            exit(EXIT_FAILURE);
        }

        // Print the reading to standard output
        printf("Received: %s\n", buffer);
    }

    // Release the hardware
    close(fd);

    return 0;
}

