#define PWM_CHANNEL_1 2
#define PWM_CHANNEL_2 3
#define PWM_CHANNEL_3 18

int main() {
    int fd, error;
    struct gpiod_device *device;
    struct gpiod_line *pwm_line;
    unsigned int pwm_duty;

    // Initialize pigpio
    if (gpiod_init() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    // Open GPIO 2, GPIO 3, and GPIO 18
    fd = gpiod_open(2, GPIDX_OUTPUT);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO 2\n");
        gpiod_exit();
        return 1;
    }
    device = gpiod_get_device(fd);
    if (device == NULL) {
        fprintf(stderr, "Error: Failed to get device for GPIO 2\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    pwm_line = gpiod_get_line(device, GPIDX_PWM);
    if (pwm_line == NULL) {
        fprintf(stderr, "Error: Failed to get PWM line for GPIO 2\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set PWM duty to 50% (half of the maximum value)
    pwm_duty = 50;
    error = gpiod_set_duty(pwm_line, pwm_duty);
    if (error < 0) {
        fprintf(stderr, "Error: Failed to set PWM duty to %d\n", pwm_duty);
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Repeat the PWM operation once every 0.15 seconds
    while (1) {
        // Wait for 0.15 seconds
        sleep(0.15);

        // Set PWM duty to 0% (off)
        pwm_duty = 0;
        error = gpiod_set_duty(pwm_line, pwm_duty);
        if (error < 0) {
            fprintf(stderr, "Error: Failed to set PWM duty to 0\n");
            gpiod_close(fd);
            gpiod_exit();
            return 1;
        }

        // Wait for 0.15 seconds
        sleep(0.15);

        // Set PWM duty to 100% (on)
        pwm_duty = 100;
        error = gpiod_set_duty(pwm_line, pwm_duty);
        if (error < 0) {
            fprintf(stderr, "Error: Failed to set PWM duty to 100\n");
            gpiod_close(fd);
            gpiod_exit();
            return 1;
        }
    }

    // Release the hardware
    gpiod_close(fd);
    gpiod_exit();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/gpiod.h>

#define GPIO_FILE "/dev/gpiochip0"
#define GPIO_LINE 18

int main() {
    int fd;
    struct gpiod_line_config line_config;
    struct gpiod_line_state line_state;
    int ret;

    // Initialize the GPIO file descriptor
    fd = open(GPIO_FILE, O_RDWR);
    if (fd < 0) {
        perror("Error opening GPIO file descriptor");
        exit(EXIT_FAILURE);
    }

    // Configure the GPIO line
    line_config.line = GPIO_LINE;
    line_config.direction = GPIGPIO_OUT;
    line_config.state = GPIGPIO_LOW;

    ret = gpiod_line_config_set(fd, &line_config);
    if (ret < 0) {
        perror("Error configuring GPIO line");
        exit(EXIT_FAILURE);
    }

    // Initialize the GPIO line state
    line_state.value = GPIGPIO_LOW;

    ret = gpiod_line_state_set(fd, &line_state);
    if (ret < 0) {
        perror("Error setting GPIO line state");
        exit(EXIT_FAILURE);
    }

    // Perform 3 cycles
    for (int i = 0; i < 3; i++) {
        // Wait for 0.1 seconds
        sleep(0.1);

        // Set the GPIO line to HIGH
        line_state.value = GPIGPIO_HIGH;
        ret = gpiod_line_state_set(fd, &line_state);
        if (ret < 0) {
            perror("Error setting GPIO line state");
            exit(EXIT_FAILURE);
        }

        // Wait for 0.1 seconds
        sleep(0.1);

        // Set the GPIO line to LOW
        line_state.value = GPIGPIO_LOW;
        ret = gpiod_line_state_set(fd, &line_state);
        if (ret < 0) {
            perror("Error setting GPIO line state");
            exit(EXIT_FAILURE);
        }
    }

    // Release the GPIO file descriptor and hardware resources
    ret = close(fd);
    if (ret < 0) {
        perror("Error closing GPIO file descriptor");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_config_unregister(fd);
    if (ret < 0) {
        perror("Error unregistering GPIO line configuration");
        exit(EXIT_FAILURE);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/gpiod.h>

int main() {
    int fd, gpio;
    struct gpiod_info info;

    // Initialize the GPIO device
    fd = gpiod_get_fd("/dev/gpiochip0");
    if (fd < 0) {
        fprintf(stderr, "Error: Unable to open GPIO device\n");
        return 1;
    }

    // Check if the device is present
    if (gpiod_get_property(fd, "name", &info.name, sizeof(info.name)) < 0) {
        fprintf(stderr, "Error: Unable to get device name\n");
        gpiod_close(fd);
        return 1;
    }

    // Check if the device is a GPIO chip
    if (strcmp(info.name, "gpiochip") != 0) {
        fprintf(stderr, "Error: This is not a GPIO chip\n");
        gpiod_close(fd);
        return 1;
    }

    // Get the number of GPIOs on the chip
    if (gpiod_get_property(fd, "num_gpios", &info.num_gpios, sizeof(info.num_gpios)) < 0) {
        fprintf(stderr, "Error: Unable to get number of GPIOs\n");
        gpiod_close(fd);
        return 1;
    }

    // Open GPIOs
    for (gpio = 2; gpio <= 9; gpio++) {
        if (gpiod_get_property(fd, "name", &info.name, sizeof(info.name)) < 0) {
            fprintf(stderr, "Error: Unable to get GPIO name\n");
            gpiod_close(fd);
            return 1;
        }

        if (gpiod_get_property(fd, "num_gpios", &info.num_gpios, sizeof(info.num_gpios)) < 0) {
            fprintf(stderr, "Error: Unable to get number of GPIOs\n");
            gpiod_close(fd);
            return 1;
        }

        if (gpiod_get_direction(fd, gpio, GPIDIO_OUTPUT) < 0) {
            fprintf(stderr, "Error: Unable to set GPIO direction\n");
            gpiod_close(fd);
            return 1;
        }

        if (gpiod_set_value(fd, gpio, 1) < 0) {
            fprintf(stderr, "Error: Unable to set GPIO value\n");
            gpiod_close(fd);
            return 1;
        }

        printf("GPIO %d: %d\n", gpio, gpiod_get_value(fd, gpio));
    }

    // Repeat every 0.05 seconds
    while (1) {
        sleep(0.05);
    }

    // Release the GPIOs
    for (gpio = 2; gpio <= 9; gpio++) {
        gpiod_set_direction(fd, gpio, GPIDIO_INPUT);
        gpiod_release(fd, gpio);
    }

    gpiod_close(fd);

    return 0;
}

