#include <stdio.h>
#include <stdlib.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#define OPT3001_ADDRESS 0x44

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    int i2c_fd;
    int result;

    // Open the I2C device file
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device file");
        exit(EXIT_FAILURE);
    }

    // Set up the I2C device file descriptor
    i2c_fd = ioctl(fd, I2C_SLAVE, OPT3001_ADDRESS);
    if (i2c_fd < 0) {
        perror("Error setting I2C device file descriptor");
        exit(EXIT_FAILURE);
    }

    // Initialize the GPIO pins for I2C communication
    if (gpio_request_from_mem(GPIO_I2C_GPIO_BASE, GPIO_I2C_GPIO_SIZE, &gpio_mem) < 0) {
        perror("Error requesting GPIO pins");
        exit(EXIT_FAILURE);
    }

    // Set up the I2C device file descriptor for read and write operations
    data.flags = I2C_RDWR;
    data.msg.i2c_rdwr.dir = I2C_RD_WR;
    data.msg.i2c_rdwr.buf = (void *)&gpio_mem;
    data.msg.i2c_rdwr.nbytes = GPIO_I2C_GPIO_SIZE;
    data.msg.i2c_rdwr.timeout = 0;

    // Read data from the OPT3001 sensor
    result = ioctl(i2c_fd, I2C_RDWR, &data);
    if (result < 0) {
        perror("Error reading data from OPT3001 sensor");
        exit(EXIT_FAILURE);
    }

    // Print the reading to standard output
    printf("Reading from OPT3001: 0x%02x\n", data.msg.i2c_rdwr.buf[0]);

    // Release the GPIO pins
    gpio_release_from_mem(gpio_mem);

    // Close the I2C device file
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/gpiod.h>

int main() {
    int fd;
    struct gpiod_event event;
    int state;

    // Initialize the GPIO device
    fd = gpiod_get_device_by_name("gpiochip0");
    if (fd < 0) {
        fprintf(stderr, "Failed to get GPIO device: %s\n", strerror(errno));
        return 1;
    }

    // Set the GPIO 17 as an output
    if (gpiod_set_direction(fd, "gpio17", GPIDIO_OUT) < 0) {
        fprintf(stderr, "Failed to set GPIO direction: %s\n", strerror(errno));
        gpiod_release(fd);
        return 1;
    }

    // Wait for the GPIO 17 to be available
    if (gpiod_get_state(fd, "gpio17", &state) < 0) {
        fprintf(stderr, "Failed to get GPIO state: %s\n", strerror(errno));
        gpiod_release(fd);
        return 1;
    }

    // Check if GPIO 17 is already set to the desired state
    if (state != 1) {
        fprintf(stderr, "GPIO 17 is already set to %d\n", state);
        gpiod_release(fd);
        return 1;
    }

    // Apply the desired state (1 for on, 0 for off)
    state = 1;
    if (gpiod_set_value(fd, "gpio17", state) < 0) {
        fprintf(stderr, "Failed to set GPIO state: %s\n", strerror(errno));
        gpiod_release(fd);
        return 1;
    }

    // Repeat every 0.5 seconds
    while (1) {
        // Wait for the next event
        event.type = GPIGPIO_EVENT_GPIO;
        event.gpio_num = 17;
        event.event_type = GPIGPIO_EVENT_GPIO_EVENT;
        event.gpio_event.gpio_event.gpio_event_type = GPIGPIO_EVENT_GPIO_EVENT_RISING;
        if (gpiod_event_get(fd, &event) < 0) {
            fprintf(stderr, "Failed to get GPIO event: %s\n", strerror(errno));
            break;
        }

        // Print the state of GPIO 17
        printf("GPIO 17 state: %d\n", event.gpio_event.gpio_event_rising.state);

        // Release the GPIO event
        if (gpiod_event_release(fd, &event) < 0) {
            fprintf(stderr, "Failed to release GPIO event: %s\n", strerror(errno));
            break;
        }
    }

    gpiod_release(fd);

    return 0;
}

