        return 1;
    }

    // Open the device
    device_fd = gpiod_get_device_by_name("gpiochip0", "18");
    if (device_fd < 0) {
        fprintf(stderr, "Failed to open device: %s\n", gpiod_error_name(errno));
        gpiod_exit();
        return 1;
    }

    // Check if the device exists
    if (gpiod_get_device_info(device_fd, &device_info) < 0) {
