#include <sys/gpiod.h>

int main() {
    int fd;
    struct gpiod_line_config line_config;
    struct gpiod_event_config event_config;
    int ret;

    // Initialize GPIO
    fd = gpiod_get_fd(2);
    if (fd < 0) {
        fprintf(stderr, "Failed to get GPIO 2 line\n");
        exit(1);
    }

    // Configure GPIO line
    line_config.line = 2;
    line_config.direction = GPIDO_DIRECTION_OUT;
    line_config.edge = GPIDO_EDGE_NONE;
    line_config.type = GPIDO_TYPE_DIGITAL;
    line_config.active_low = 0;

    ret = gpiod_set_line_config(fd, &line_config);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 2 line configuration\n");
        exit(1);
    }

    // Configure GPIO event
    event_config.line = 2;
    event_config.event_type = GPIDO_EVENT_TYPE_RISING_EDGE;
    event_config.event_edge = GPIDO_EVENT_EDGE_RISING;

    ret = gpiod_set_event_config(fd, &event_config);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 2 event configuration\n");
        exit(1);
    }

    // Check and report the initial state
    int initial_state;
    ret = gpiod_get_line_level(fd, 2, &initial_state);
    if (ret < 0) {
        fprintf(stderr, "Failed to read initial GPIO state\n");
        exit(1);
    }

    if (initial_state == 0) {
        printf("GPIO 2 is set to high\n");
    } else {
        printf("GPIO 2 is set to low\n");
    }

    // Continuously check and report the state
    while (1) {
        int state;
        ret = gpiod_get_line_level(fd, 2, &state);
        if (ret < 0) {
            fprintf(stderr, "Failed to read GPIO state\n");
            exit(1);
        }

        if (state == 1) {
            printf("GPIO 2 is set to high\n");
        } else {
            printf("GPIO 2 is set to low\n");
        }

        // Wait for some time before checking again
        sleep(1);
    }

    // Release GPIO resources
    gpiod_release(fd);

    return 0;
}

