#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/serial.h>

#define UART_DEVICE "/dev/ttyS0" // Replace with your UART device path
#define BAUDRATE B9600

int main() {
    int fd;
    struct termios options;
    struct serial_struct* serial;

    // Open the UART device
    fd = open(UART_DEVICE, O_RDWR | O_NOCTTY);
    if (fd < 0) {
        perror("Error opening UART device");
        exit(EXIT_FAILURE);
    }

    // Set the baud rate
    if (tcgetattr(fd, &options) < 0) {
        perror("Error setting baud rate");
        exit(EXIT_FAILURE);
    }
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~CRTSCTS;
    options.c_cflag |= CREAD | CLOCAL;
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_iflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;
    options.c_cc[VMIN] = 0;
    options.c_cc[VTIME] = 10;
    if (tcsetattr(fd, TCSANOW, &options) < 0) {
        perror("Error setting serial port options");
        exit(EXIT_FAILURE);
    }

    // Initialize the serial port
    serial = (struct serial_struct*)malloc(sizeof(struct serial_struct));
    if (!serial) {
        perror("Error allocating memory for serial port");
        exit(EXIT_FAILURE);
    }
    serial->handle = open(UART_DEVICE, O_RDWR);
    if (serial->handle < 0) {
        perror("Error opening UART device");
        exit(EXIT_FAILURE);
    }

    // Set the serial port parameters
    if (ioctl(serial->handle, TIOCMGET, &serial->c_cflag) < 0) {
        perror("Error getting serial port parameters");
        exit(EXIT_FAILURE);
    }
    serial->c_cflag &= ~CRTSCTS;
    serial->c_cflag |= CREAD | CLOCAL;
    serial->c_iflag &= ~(IXON | IXOFF | IXANY);
    serial->c_iflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    serial->c_oflag &= ~OPOST;
    serial->c_cc[VMIN] = 0;
    serial->c_cc[VTIME] = 10;

    // Read from the serial port
    char buffer[256];
    int bytes_read = 0;
    while (1) {
        if (read(serial->handle, &buffer[bytes_read], sizeof(buffer) - bytes_read) < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("Error reading from serial port");
            exit(EXIT_FAILURE);
        }
        bytes_read += sizeof(buffer) - bytes_read;
        printf("Received: %s\n", buffer);
    }

    // Close the serial port and release resources
    close(serial->handle);
    free(serial);

    return 0;
}

