    struct gpiod_event_state state;
    int ret;

    // Initialize GPIO
    fd = gpiod_get_fd(GPIO_NUMBER);
    if (fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    // Set the digital output to a valid state
    state.value = VALID_READ_VALUE;
    ret = gpiod_event_state_set(fd, GPIO_NUMBER, &state);
    if (ret < 0) {
        fprintf(stderr, "Failed to set digital output state: %s\n", strerror(errno));
        gpiod_close(fd);
        return 1;
    }

    // Repeat the process every 60 seconds
    while (1) {
        // Check the state
        ret = gpiod_event_state_get(fd, GPIO_NUMBER, &state);
        if (ret < 0) {
            fprintf(stderr, "Failed to get digital output state: %s\n", strerror(errno));
            continue;
        }

        // Check if the state is valid
        if (state.value != VALID_READ_VALUE) {
            fprintf(stderr, "Invalid state value: %d\n", state.value);
            continue;
        }

        // Report the state
        printf("Digital output state: %d\n", state.value);

        // Release the hardware
        ret = gpiod_event_state_clear(fd, GPIO_NUMBER, &state);
        if (ret < 0) {
            fprintf(stderr, "Failed to clear digital output state: %s\n", strerror(errno));
            gpiod_close(fd);
            return 1;
        }

        // Wait for 60 seconds
        sleep(60);
    }

    // Release the hardware on all exit paths
    gpiod_close(fd);
