    if ((pwm_fd = gpiod_open(GPIO_OUTPUT_PWM, GPIO_UNUSED)) < 0) {
        fprintf(stderr, "Failed to open PWM GPIO file descriptor\n");
        return 1;
    }

    if ((gpio_fd = gpiod_open(GPIO_UNUSED, GPIO_UNUSED)) < 0) {
        fprintf(stderr, "Failed to open GPIO file descriptor\n");
        return 1;
    }

    // Set PWM channel
    if (gpiod_set_direction(pwm_fd, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PWM direction\n");
        return 1;
    }

    // Set PWM state
    if (gpiod_set_value(pwm_fd, state) < 0) {
        fprintf(stderr, "Failed to set PWM state\n");
        return 1;
    }

    // Set PWM frequency
    if (gpiod_set_frequency(pwm_fd, 100) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return 1;
    }

    // Set PWM duty cycle
    if (gpiod_set_value(pwm_fd, state) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        return 1;
    }

    // Set PWM state to 0 to start the PWM
    state = 0;

    // Repeat the PWM cycle every 5 seconds
    while (1) {
        // Wait for 5 seconds
        sleep(5);

        // Update PWM state
        state = (state + 1) % 256;

        // Check if PWM state is within the range (0-255)
