int main() {
    int fd, gpio_file, i2c_file, i2c_fd;
    struct w1_bus_handle *bus;
    struct w1_device *device;
    char temp_str[12];
    int valid_reading = 0;
    int error_code = 0;

    // Initialize GPIO and sysfs-w1
    if (gpio_init() < 0) {
        fprintf(stderr, "Error initializing GPIO\n");
        return 1;
    }

    if (sysfs_w1_init() < 0) {
        fprintf(stderr, "Error initializing sysfs-w1\n");
        return 1;
    }

    // Open GPIO file
    if ((gpio_file = open("/dev/gpiomem", O_RDWR)) < 0) {
        fprintf(stderr, "Error opening GPIO file\n");
        return 1;
    }

    // Open I2C file
    if ((i2c_file = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Error opening I2C file\n");
        return 1;
    }

    // Open DS18B20 device file
    if ((i2c_fd = open(DS18B20_DEVICE_PATH, I2C_NOCLOBBER)) < 0) {
        fprintf(stderr, "Error opening DS18B20 device file\n");
        return 1;
    }

    // Open sysfs-w1 device file
    if ((bus = w1_bus_new()) == NULL) {
        fprintf(stderr, "Error initializing sysfs-w1 bus\n");
        return 1;
    }

    if (w1_bus_add_device(bus, DS18B20_TEMP_SLAVE_ID, DS18B20_DEVICE_PATH) < 0) {
        fprintf(stderr, "Error adding DS18B20 device to sysfs-w1 bus\n");
        return 1;
    }

    // Read temperature from DS18B20
    while (1) {
        if (w1_device_read_temp(device, temp_str, sizeof(temp_str)) < 0) {
            fprintf(stderr, "Error reading temperature from DS18B20\n");
            return 1;
        }

        // Check if the reading is valid
        if (sscanf(temp_str, "%d.%d", &temp_str[0], &temp_str[1]) != 2) {
            fprintf(stderr, "Invalid temperature reading from DS18B20\n");
            continue;
        }

        // Print the temperature to standard output
        printf("Temperature: %.2f C\n", atof(temp_str));

        // Check if the reading is valid
        if (!valid_reading) {
            fprintf(stderr, "Invalid temperature reading from DS18B20\n");
            continue;
        }

        // Check if the device is absent
        if (ioctl(i2c_file, I2C_RDWR, 0) < 0) {
            fprintf(stderr, "Error reading from DS18B20 device\n");
            error_code = 1;
            break;
        }

        // Release the hardware
        if (close(i2c_file) < 0) {
            fprintf(stderr, "Error closing I2C file\n");
            error_code = 1;
            break;
        }

        if (close(i2c_fd) < 0) {
            fprintf(stderr, "Error closing sysfs-w1 I2C file\n");
            error_code = 1;
            break;
        }

        if (close(bus) < 0) {
            fprintf(stderr, "Error closing sysfs-w1 bus\n");
            error_code = 1;
            break;
        }

        if (gpio_close(gpio_file) < 0) {
            fprintf(stderr, "Error closing GPIO file\n");
            error_code = 1;
            break;
        }

        if (gpio_close(i2c_file) < 0) {
            fprintf(stderr, "Error closing I2C file\n");
            error_code = 1;
            break;
        }

        if (gpio_close(bus) < 0) {
            fprintf(stderr, "Error closing sysfs-w1 bus\n");
            error_code = 1;
            break;
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Release resources on exit
    if (close(bus) < 0) {
        fprintf(stderr, "Error closing sysfs-w1 bus\n");
        error_code = 1;
    }

    if (close(i2c_fd) < 0) {
        fprintf(stderr, "Error closing sysfs-w1 I2C file\n");
        error_code = 1;
    }

    if (close(i2c_file) < 0) {
        fprintf(stderr, "Error closing I2C file\n");
        error_code = 1;
    }

    if (close(gpio_file) < 0) {
        fprintf(stderr, "Error closing GPIO file\n");
        error_code = 1;
    }

    if (close(bus) < 0) {
        fprintf(stderr, "Error closing sysfs-w1 bus\n");
        error_code = 1;
    }

    if (error_code) {
        printf("Error: %d\n", error_code);
        return 1;
    }

    return 0;
}

