#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#define I2C_ADDR 0x53
#define I2C_SLAVE_ADDR 0x53

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg[2];
    int ret;

    // Open the I2C device file
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device file");
        exit(EXIT_FAILURE);
    }

    // Set the I2C slave address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        exit(EXIT_FAILURE);
    }

    // Initialize the I2C bus
    if (ioctl(fd, I2C_RDWR, I2C_ADDR) < 0) {
        perror("Error initializing I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set the I2C transfer direction
    msg[0].addr = I2C_ADDR;
    msg[0].flags = 0;
    msg[0].len = 1;
    msg[0].buf = &data;
    msg[0].buf_len = sizeof(struct i2c_rdwr_ioctl_data);

    data.flags = 0;
    data.timeout = 0;
    data.no_setup = 0;
    data.mode = I2C_MODE_I2C;
    data.write = 1;
    data.write_length = 1;
    data.read = 0;
    data.read_length = 0;

    // Perform the I2C transfer
    if (ioctl(fd, I2C_RDWR, &msg[0]) < 0) {
        perror("Error performing I2C transfer");
        exit(EXIT_FAILURE);
    }

    // Read the data from the ADXL345
    ret = ioctl(fd, I2C_RDWR, &msg[1]);
    if (ret < 0) {
        perror("Error reading data from ADXL345");
        exit(EXIT_FAILURE);
    }

    // Print the reading to standard output
    printf("Reading: %d\n", *(int*)msg[1].buf);

    // Wait for 0.1 seconds
    sleep(0.1);

    // Release the I2C bus
    if (ioctl(fd, I2C_RDWR, I2C_ADDR) < 0) {
        perror("Error releasing I2C bus");
        exit(EXIT_FAILURE);
    }

    // Close the I2C device file
    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/gpiod.h>

#define GPIO_FILE "/dev/gpiochip0"
#define GPIO_LINE 27

int main() {
    int fd;
    struct gpiod_line_config line_config;
    struct gpiod_event_config event_config;
    struct gpiod_event event;
    int cycles = 50;
    int delay_ms = 100;

    // Initialize the GPIO chip
    fd = open(GPIO_FILE, O_RDWR);
    if (fd < 0) {
        perror("Error opening GPIO chip file");
        exit(EXIT_FAILURE);
    }

    // Configure the GPIO line
    line_config.line = GPIO_LINE;
    line_config.direction = GPIGPIO_OUT;
    if (ioctl(fd, GPIGPIO_LINE_CONFIG_ALL, &line_config) < 0) {
        perror("Error configuring GPIO line");
        exit(EXIT_FAILURE);
    }

    // Initialize the event
    event_config.event_type = GPIGPIO_EVENT_RISING;
    event_config.event_edge = GPIGPIO_EVENT_RISING;
    event.event_config = event_config;

    // Loop for 50 cycles
    for (int i = 0; i < cycles; i++) {
        if (ioctl(fd, GPIGPIO_EVENT_SET, &event) < 0) {
            perror("Error setting event");
            exit(EXIT_FAILURE);
        }

        // Wait for 0.1 seconds
        usleep(delay_ms * 1000);

        // Check the state of the GPIO line
        if (ioctl(fd, GPIGPIO_LINE_GET, &event) < 0) {
            perror("Error getting GPIO line state");
            exit(EXIT_FAILURE);
        }

        printf("GPIO 27 state: %d\n", event.state);
    }

    // Release the GPIO chip
    if (ioctl(fd, GPIGPIO_RELEASE, GPIO_FILE) < 0) {
        perror("Error releasing GPIO chip");
        exit(EXIT_FAILURE);
    }

    close(fd);
    return 0;
}

