    fd = gpio_open(PWM_CHANNEL_22);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO 22\n");
        return 1;
    }
    pwm_channels[pwm_channels_count++] = (struct gpiod_channel *)fd;

    fd = gpio_open(PWM_CHANNEL_27);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO 27\n");
        return 1;
    }
    pwm_channels[pwm_channels_count++] = (struct gpiod_channel *)fd;

    // Set PWM frequency to 50 Hz
    if (gpio_set_mode(pwm_channels[0], GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set PWM mode\n");
        return 1;
    }
    if (gpio_set_dir(pwm_channels[0], GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set PWM direction\n");
        return 1;
