    if (gpio_set_freq(pwm_channels[0], 50) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency\n");
        return 1;
    }

    // Set PWM duty cycle to 50%
    if (gpio_set_pwm(pwm_channels[0], 0, 0, 50) < 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle\n");
        return 1;
    }

    // Repeat every 0.5 seconds
    while (1) {
        // Print the current PWM duty cycle
        printf("PWM Duty Cycle: %d\n", gpio_get_pwm(pwm_channels[0], 0));

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Release resources
    for (int i = 0; i < pwm_channels_count; i++) {
        gpio_close(pwm_channels[i]);
    }
    gpio_exit();

    return 0;
}

