#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/gpiod.h>

int main() {
    int fd;
    struct gpiod_event event;
    int state;

    // Initialize the GPIO device
    fd = gpiod_get_device_by_name("gpiochip0");
    if (fd < 0) {
        fprintf(stderr, "Failed to get GPIO device: %s\n", strerror(errno));
        return 1;
    }

    // Set the GPIO pin as an output
    if (gpiod_set_direction(fd, "gpiochip0", 22, GPIDX_OUT) < 0) {
        fprintf(stderr, "Failed to set GPIO direction: %s\n", strerror(errno));
        gpiod_close(fd);
        return 1;
    }

    // Wait for the GPIO pin to be available
    if (gpiod_get_state(fd, "gpiochip0", 22, &state) < 0) {
        fprintf(stderr, "Failed to get GPIO state: %s\n", strerror(errno));
        gpiod_close(fd);
        return 1;
    }

    // Check if the GPIO pin is already in the desired state
    if (state == 0) {
        printf("Digital output is already set to 0\n");
        return 0;
    }

    // Apply the desired state to the GPIO pin
    state = 1;
    if (gpiod_set_value(fd, "gpiochip0", 22, state) < 0) {
        fprintf(stderr, "Failed to set GPIO value: %s\n", strerror(errno));
        gpiod_close(fd);
        return 1;
    }

    // Repeat the process
    while (1) {
        // Wait for the next event
        event.type = GPIDEV_EVENT_GPIO;
        event.gpio = 22;
        event.state = state;
        if (gpiod_event_poll(fd, 1, &event, 1) < 0) {
            fprintf(stderr, "Failed to poll GPIO event: %s\n", strerror(errno));
            gpiod_close(fd);
            return 1;
        }

        // Print the current state
        printf("Digital output is now %d\n", state);
    }

    // Release the GPIO device
    gpiod_close(fd);

