        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    // Open the PWM output line
    fd = gpiod_open(GPIDO_DIR_OUT, PWM_OUTPUT_PIN);
    if (fd < 0) {
        fprintf(stderr, "Error opening PWM output line\n");
        gpiod_exit();
        return 1;
    }

    // Get the PWM line
    device = gpiod_get_device(fd);
    if (device == NULL) {
        fprintf(stderr, "Error getting PWM line\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Get the PWM line
    line = gpiod_get_line(device, "PWM");
    if (line == NULL) {
        fprintf(stderr, "Error getting PWM line\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set the PWM frequency
    error = gpiod_set_property(line, "format", "int");
    if (error < 0) {
        fprintf(stderr, "Error setting PWM frequency format\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }
    error = gpiod_set_property(line, "value", PWM_FREQUENCY);
    if (error < 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set the PWM duty cycle
    error = gpiod_set_property(line, "duty", PWM_FREQUENCY / 2);
    if (error < 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set the PWM state
    error = gpiod_set_value(line, 1);
    if (error < 0) {
        fprintf(stderr, "Error setting PWM state\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Repeat every 0.02 seconds
    while (1) {
        // Print the PWM state
        printf("PWM state: %d\n", gpiod_get_value(line));

        // Wait for 0.02 seconds
        sleep(0.02);
    }

    // Release the PWM line
    gpiod_release(line);
    gpiod_close(fd);
    gpiod_exit();

    return 0;
