int main() {
    int fd, ret;
    struct gpiod_device *device;
    int state;

    // Initialize the GPIO device
    fd = gpiod_get_device("/dev/gpiochip0");
    if (fd < 0) {
        fprintf(stderr, "Error: Unable to get device\n");
        return 1;
    }

    // Check if the device is present
    ret = gpiod_get_state(fd, "gpio22", &state);
    if (ret < 0) {
        fprintf(stderr, "Error: Unable to get GPIO 22 state\n");
        gpiod_close(fd);
        return 1;
    }

    if (state == 0) {
        fprintf(stdout, "GPIO 22 is set to 0\n");
    } else {
        fprintf(stdout, "GPIO 22 is set to 1\n");
    }

    // Repeat the process
    while (1) {
        ret = gpiod_get_state(fd, "gpio22", &state);
        if (ret < 0) {
            fprintf(stderr, "Error: Unable to get GPIO 22 state\n");
            gpiod_close(fd);
            return 1;
        }

        if (state == 0) {
            fprintf(stdout, "GPIO 22 is set to 0\n");
        } else {
            fprintf(stdout, "GPIO 22 is set to 1\n");
        }

        usleep(10000); // Wait for 10 milliseconds
    }

    // Release the GPIO device
    gpiod_close(fd);

    return 0;
