        gpiod_unregister(device);
        return 1;
    }
    ret = gpiod_set_value(fd, "gpiochip0", "gpio5", direction, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Unable to set GPIO5 value to 0\n");
        gpiod_close(fd);
        gpiod_unregister(device);
        return 1;
    }

    // Repeat every 5 seconds
    while (1) {
        // Check the state of GPIO 2, GPIO 3, and GPIO 5
        ret = gpiod_get_value(fd, "gpiochip0", "gpio2", &value);
        if (ret < 0) {
            fprintf(stderr, "Error: Unable to get GPIO2 value\n");
