#define PWM_CHANNEL_COUNT 4

int main() {
    int pwm_fd, gpio_fd;
    struct gpiod_channel_state state;
    int i;

    // Initialize pigpio library
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open GPIO file descriptors
    pwm_fd = gpio_open("/dev/pigpio", GPIO_DIR_OUT);
    if (pwm_fd < 0) {
        fprintf(stderr, "Failed to open GPIO file descriptor\n");
        return 1;
    }

    gpio_set_mode(pwm_fd, GPIO_OUTPUT);

    for (i = 0; i < PWM_CHANNEL_COUNT; i++) {
        gpio_set_dir(pwm_fd, i + 1);
        gpio_set_value(pwm_fd, i + 1);
    }

    // Repeat the PWM output every 1 second
    while (1) {
        // Get the current state of the PWM channels
        if (gpiod_get_channel_state(pwm_fd, PWM_CHANNEL_COUNT, &state) < 0) {
            fprintf(stderr, "Failed to get PWM channel state\n");
            return 1;
        }

        // Print the PWM state
        printf("PWM Channel %d: %d\n", i + 1, state.level);

        // Wait for 1 second
        sleep(1);
    }

    // Release the GPIO file descriptors and pigpio resources
    gpio_close(pwm_fd);
    gpio_uninit();

    return 0;
}

#include <stdio.h>
