#define SENSOR_PIN 17
#define ECHO_PIN 23
#define TRIG_PIN 24

int main() {
    int fd, gpio_direction, gpio_value;
    struct gpiod_event event;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open GPIO pins
    fd = gpiod_get_direction(SENSOR_PIN);
    if (fd < 0) {
        fprintf(stderr, "Failed to get direction for GPIO %d\n", SENSOR_PIN);
        gpiod_exit();
        return 1;
    }

    gpio_direction = gpiod_get_state(fd);
    if (gpio_direction & (1 << SENSOR_PIN)) {
        fprintf(stderr, "Sensor is already active\n");
        gpiod_exit();
        return 1;
    }

    gpio_direction |= (1 << SENSOR_PIN);
    if (gpiod_set_direction(fd, gpio_direction) < 0) {
        fprintf(stderr, "Failed to set direction for GPIO %d\n", SENSOR_PIN);
        gpiod_exit();
        return 1;
    }

    // Set trigger pin to output
    gpio_value = 0;
    if (gpiod_set_value(ECHO_PIN, gpio_value) < 0) {
        fprintf(stderr, "Failed to set value for GPIO %d\n", ECHO_PIN);
        gpiod_exit();
        return 1;
    }

    // Set trigger pin to input
    gpio_value = 1;
    if (gpiod_set_value(TRIG_PIN, gpio_value) < 0) {
        fprintf(stderr, "Failed to set value for GPIO %d\n", TRIG_PIN);
        gpiod_exit();
        return 1;
    }

    // Wait for the sensor to trigger
    event.type = GPIGPIO_EVENT_TYPE_GPIO;
    event.gpio.gpio_num = ECHO_PIN;
    event.gpio.event_type = GPIGPIO_EVENT_GPIO_TRIGGER_FALLING;
    event.gpio.event_data = 0;

    while (1) {
        if (gpiod_wait_event(fd, &event, 0, NULL) < 0) {
            fprintf(stderr, "Failed to wait for event\n");
            gpiod_exit();
            return 1;
        }

        if (event.gpio.event_type == GPIGPIO_EVENT_GPIO_TRIGGER_FALLING) {
            gpio_value = 1;
            if (gpiod_set_value(ECHO_PIN, gpio_value) < 0) {
                fprintf(stderr, "Failed to set value for GPIO %d\n", ECHO_PIN);
                gpiod_exit();
                return 1;
            }
        } else {
            gpio_value = 0;
            if (gpiod_set_value(ECHO_PIN, gpio_value) < 0) {
                fprintf(stderr, "Failed to set value for GPIO %d\n", ECHO_PIN);
                gpiod_exit();
                return 1;
            }
        }

        // Print the sensor's distance
        // Replace this with your own code to read the sensor's output
        printf("Distance: %d cm\n", (int)(event.gpio.event_data * 2.54 / 100));
    }

    gpiod_exit();
    return 0;
}

