    struct gpiod_line_state line_state;

    // Initialize pigpio
    if (gpiod_init() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO line configuration
    line_config.line = GPIO_LINE;
    line_config.direction = GPIGPIO_OUT_PPM;
    line_config.state = GPIGPIO_LOW;

    // Open GPIO line
    fd = gpiod_get_line(line_config);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO line\n");
        gpiod_exit();
        return 1;
    }

    // Set up the strip
    line_state.state = GPIGPIO_LOW;
    error = gpiod_set_line_state(fd, line_state);
    if (error < 0) {
        fprintf(stderr, "Error: Failed to set GPIO line state\n");
        gpiod_exit();
        return 1;
    }

    // Set pixel colours
    for (int i = 0; i < PIXEL_COUNT; i++) {
        int red = i * 255 / PIXEL_COUNT;
        int green = i * 255 / PIXEL_COUNT;
        int blue = i * 255 / PIXEL_COUNT;

        line_state.state = GPIGPIO_HIGH;
        error = gpiod_set_line_state(fd, line_state);
        if (error < 0) {
            fprintf(stderr, "Error: Failed to set GPIO line state\n");
            gpiod_exit();
            return 1;
        }

        // Wait for 0.01 seconds
        sleep(0.01);

        line_state.state = GPIGPIO_LOW;
        error = gpiod_set_line_state(fd, line_state);
        if (error < 0) {
            fprintf(stderr, "Error: Failed to set GPIO line state\n");
            gpiod_exit();
            return 1;
        }
    }

    // Release GPIO line
    gpiod_release(fd);

    // Clean up
    gpiod_exit();

    return 0;
}

