#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/i2c-gpio.h>

#define BME280_ADDRESS 0x76

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    int ret;

    // Open the I2C bus
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set the I2C address of the BME280 sensor
    if (ioctl(fd, I2C_SLAVE, BME280_ADDRESS) < 0) {
        perror("Error setting I2C address");
        exit(EXIT_FAILURE);
    }

    // Initialize the BME280 sensor
    if (ioctl(fd, BME280_INIT, 0) < 0) {
        perror("Error initializing BME280 sensor");
        exit(EXIT_FAILURE);
    }

    // Repeat reading every 5 seconds
    while (1) {
        // Clear the screen
        if (system("clear") != 0) {
            perror("Error clearing the screen");
            exit(EXIT_FAILURE);
        }

        // Print the reading to standard output
        printf("Reading from BME280: %d\n", bme280_read_temperature());
        printf("Reading from BME280: %d\n", bme280_read_pressure());
        printf("Reading from BME280: %d\n", bme280_read_humidity());

        // Wait for 5 seconds
        sleep(5);
    }

    // Release the I2C bus and hardware resources
    close(fd);
    return 0;
}

