    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    struct i2c_client *client;
    int i2c_client_fd;

    // Initialize i2c_client_fd
    i2c_client_fd = i2c_init();

    if (i2c_client_fd < 0) {
        fprintf(stderr, "Error initializing i2c_client_fd\n");
        return 1;
    }

    // Open i2c bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening i2c bus\n");
        return 1;
    }

    // Set up i2c device address
    client = i2c_init_client(i2c_fd, I2C_ADDR);
    if (client == NULL) {
        fprintf(stderr, "Error initializing i2c device\n");
        return 1;
    }

    // Set up i2c message structure
    i2c_msgs[0].addr = client->addr;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 2;
    i2c_msgs[0].buf = (void *)&i2c_data;

    // Set up i2c message structure for reading data
    i2c_msgs[1].addr = client->addr;
    i2c_msgs[1].flags = I2C_M_RD;
    i2c_msgs[1].len = 2;
    i2c_msgs[1].buf = (void *)&i2c_data;

    // Perform i2c read
    rc = i2c_transfer(i2c_fd, i2c_msgs, 2, NULL);
    if (rc < 0) {
        fprintf(stderr, "Error performing i2c read\n");
        return 1;
    }

    // Close i2c device
    close(i2c_fd);

    // Repeat the process
    while (1) {
        // Wait for 0.2 seconds
        sleep(0.2);

        // Perform i2c read
        rc = i2c_transfer(i2c_fd, i2c_msgs, 2, NULL);
        if (rc < 0) {
            fprintf(stderr, "Error performing i2c read\n");
            return 1;
        }

        // Print the reading to standard output
        printf("ADC reading: %d\n", i2c_data.data);
    }

    // Release i2c device
    i2c_release_client(client);

    return 0;
}

