int main() {
    int fd;
    struct gpiod_device *device;
    int state;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open GPIO 4
    if ((fd = gpiod_open(4, GPIDX_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to open GPIO 4\n");
        gpiod_exit();
        return 1;
    }

    // Get the device structure
    device = gpiod_get_device(fd);

    // Check if the device exists
    if (device == NULL) {
        fprintf(stderr, "Device not found\n");
        gpiod_exit();
        return 1;
    }

    // Set the digital output to a state
    if (gpiod_set_value(device, 1) < 0) {
        fprintf(stderr, "Failed to set digital output to 1\n");
        gpiod_exit();
        return 1;
    }

    // Check the state of the digital output
    if (gpiod_get_value(device) != 1) {
        fprintf(stderr, "Digital output is not set to 1\n");
        gpiod_exit();
        return 1;
    }

    // Repeat the process
    while (1) {
        // Check for interrupts
        if (gpiod_interrupt_check(device) > 0) {
            fprintf(stderr, "Interrupt detected on GPIO 4\n");
            break;
        }

        // Wait for 60 seconds
        sleep(60);

        // Check the state of the digital output
        if (gpiod_get_value(device) != 1) {
            fprintf(stderr, "Digital output is not set to 1\n");
            break;
        }
    }

    // Release the GPIO device
    gpiod_release(device);

    // Cleanup
    gpiod_exit();

    return 0;
}

