#include <stdio.h>
#include <stdlib.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#define I2C_DEVICE_ADDRESS 0x68
#define I2C_I2C_GPIO_PIN 17

int main() {
    int rc;
    int i;
    int device_fd;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg[2];
    int num_readings = 0;
    int measurements[100];

    // Open the I2C device file
    device_fd = open("/dev/i2c-1", O_RDWR);
    if (device_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C device file\n");
        return 1;
    }

    // Set the I2C GPIO pin as an output
    rc = ioctl(device_fd, I2C_RDWR, I2C_I2C_GPIO_PIN);
    if (rc < 0) {
        fprintf(stderr, "Error: Could not set I2C GPIO pin as output\n");
        return 1;
    }

    // Set the I2C device address
    rc = ioctl(device_fd, I2C_SLAVE, I2C_DEVICE_ADDRESS);
    if (rc < 0) {
        fprintf(stderr, "Error: Could not set I2C device address\n");
        return 1;
    }

    // Initialize the MPU6050
    rc = gpiod_set_direction(I2C_I2C_GPIO_PIN, GPIO_MODE_OUTPUT);
    if (rc < 0) {
        fprintf(stderr, "Error: Could not set I2C GPIO direction\n");
        return 1;
    }

    // Perform the I2C read operation
    for (i = 0; i < 100; i++) {
        msg[0].addr = I2C_DEVICE_ADDRESS;
        msg[0].flags = 0;
        msg[0].len = 1;
        msg[0].buf = &measurements[i];

        msg[1].addr = I2C_DEVICE_ADDRESS;
        msg[1].flags = 0;
        msg[1].len = 1;
        msg[1].buf = &measurements[i + 1];

        data.msgs = msg;
        data.nmsgs = 2;

        rc = ioctl(device_fd, I2C_RDWR, &data);
        if (rc < 0) {
            fprintf(stderr, "Error: Could not perform I2C read operation\n");
            return 1;
        }

        // Print the measurement to standard output
        printf("Measurement: %d\n", measurements[i]);
    }

    // Release the I2C device file
    close(device_fd);

    return 0;
}

