// Function to handle MQTT callbacks
void on_connect(int result, mqtt_client_t* client, void* userdata) {
    printf("Connected to MQTT broker with result code %d\n", result);
}

void on_publish(int result, mqtt_client_t* client, void* userdata) {
    printf("Published message to topic %s\n", TOPIC);
}

void on_error(int result, mqtt_client_t* client, void* userdata) {
    printf("MQTT error: %s\n", mqtt_strerror(result));
}

void publish_sensor_data(int sensor_value) {
    // Perform the MQTT publish operation
    int result = mqtt_publish(mqtt_client, TOPIC, sensor_value, 0, NULL, 0);
    if (result != 0) {
        printf("Failed to publish sensor data: %d\n", result);
    }
}

int main() {
    // Initialize MQTT client
    mqtt_client_t* client = mqtt_client_new();
    if (client == NULL) {
        printf("Failed to create MQTT client\n");
        return 1;
    }

    // Set MQTT callbacks
    mqtt_on_connect_t on_connect = on_connect;
    mqtt_on_publish_t on_publish = on_publish;
    mqtt_on_error_t on_error = on_error;
    mqtt_set_on_connect_cb(client, &on_connect);
    mqtt_set_on_publish_cb(client, &on_publish);
    mqtt_set_on_error_cb(client, &on_error);

    // Connect to MQTT broker
    int result = mqtt_connect(client, "localhost", 1883, 0);
    if (result != 0) {
        printf("Failed to connect to MQTT broker: %d\n", result);
        mqtt_client_free(client);
        return 1;
    }

    // Set MQTT options
    mqtt_opts_t opts = MQTT_DEFAULT_OPTIONS;
    opts.clean_session = 1;
    opts.reconnect_interval_ms = 1000;
    opts.reconnect_backoff_ms = 1000;
    opts.userdata = client;

    // Set MQTT topic
    result = mqtt_subscribe(client, TOPIC, 1, &opts);
    if (result != 0) {
        printf("Failed to subscribe to topic: %d\n", result);
        mqtt_client_free(client);
        return 1;
    }

    // Set up I2C communication
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        printf("Failed to open I2C device: %s\n", "/dev/i2c-1");
        return 1;
    }

    struct i2c_rdwr_ioctl_data data;
    memset(&data, 0, sizeof(data));
    data.flags = 0;
    data.addr = I2C_DEVICE_ADDRESS;
    data.nbytes = 1;
    data.buf = malloc(1);
    if (data.buf == NULL) {
        printf("Failed to allocate memory for I2C buffer\n");
        close(fd);
        return 1;
    }

    // Read sensor data
    int sensor_value = 0;
    result = i2c_smbus_read_byte_data(fd, 0x1A, &sensor_value);
    if (result != 0) {
        printf("Failed to read sensor data: %d\n", result);
        free(data.buf);
        close(fd);
        return 1;
    }

    // Publish sensor data
    publish_sensor_data(sensor_value);

    // Set up pthread for interval publishing
    pthread_t thread;
    pthread_create(&thread, NULL, publish_sensor_data_interval, NULL);

    // Infinite loop to publish sensor data every 0.01 seconds
    while (1) {
        // Wait for MQTT message
        mqtt_message_t* message = mqtt_message_new();
        result = mqtt_client_loop(client, &message);
        if (result != 0) {
            printf("Failed to loop MQTT client: %d\n", result);
            break;
        }

        // Check if message is from MQTT broker
        if (message->topic_name && strcmp(message->topic_name, TOPIC) == 0) {
            // Publish sensor data
            publish_sensor_data(sensor_value);
        }
    }

    // Clean up
    mqtt_client_free(client);
    close(fd);
    free(data.buf);

    return 0;
}

// Function to publish sensor data every 0.01 seconds
void publish_sensor_data_interval(void* arg) {
    while (1) {
        // Wait for MQTT message
        mqtt_message_t* message = mqtt_message_new();
