        fprintf(stderr, "Failed to get device: %s\n", strerror(errno));
        return 1;
    }

    // Set the GPIO 23 as an output
    if (gpiod_set_direction(fd, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set direction: %s\n", strerror(errno));
        gpiod_close(fd);
        return 1;
    }

    // Set the initial state of the GPIO 23 to 0
    if (gpiod_set_value(fd, GPIO_23, 0) < 0) {
        fprintf(stderr, "Failed to set value: %s\n", strerror(errno));
        gpiod_close(fd);
        return 1;
    }

    // Repeat every 5 seconds
    while (1) {
        // Wait for the next event
        memset(&event, 0, sizeof(event));
        event.type = GPIGPIO_EVENT_GPIO_EVENT;
        event.gpio_num = 23;
        event.event_type = GPIGPIO_EVENT_GPIO_EVENT_STATE_CHANGED;
        event.state = gpiod_get_value(fd, GPIO_23);

        if (gpiod_event_wait(fd, &event, NULL) < 0) {
            fprintf(stderr, "Failed to wait for event: %s\n", strerror(errno));
            continue;
        }

        // Print the state of GPIO 23
        state = event.state;
