    struct gpiod_event event;
    int valid_distance = 0;
    int valid_distance_old = 0;
    int distance = 0;

    fd = gpiod_get_fd(SENSOR_PIN);
    if (fd < 0) {
        perror("Failed to get sensor file descriptor");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_event_request(fd, GPIGPIO_EVENT_LEVEL_HIGH, SENSOR_PIN, &event);
    if (ret < 0) {
        perror("Failed to request event");
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = gpiod_event_wait(fd, &event);
        if (ret < 0) {
            perror("Failed to wait for event");
            exit(EXIT_FAILURE);
        }

        if (event.state == GPIGPIO_EVENT_STATE_ACTIVE) {
            distance = event.value;
            valid_distance = 1;
