    int state;

    // Initialize pigpio library
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open GPIO channels
    for (pwm_gpio_num = 0; pwm_gpio_num < PWM_CHANNELS; pwm_gpio_num++) {
        gpio_channel = gpiod_get_channel(pwm_gpio_num);
        if (gpio_channel == NULL) {
            fprintf(stderr, "Failed to open GPIO channel %d\n", pwm_gpio_num);
            gpiod_exit();
            return 1;
        }

        pwm_gpio_fd = gpiod_get_file(gpio_channel);
        if (pwm_gpio_fd < 0) {
            fprintf(stderr, "Failed to get file descriptor for GPIO %d\n", pwm_gpio_num);
            gpiod_exit();
            return 1;
        }

        pwm_channel = gpiod_get_channel_by_name(pwm_gpio_num);
        if (pwm_channel == NULL) {
            fprintf(stderr, "Failed to get channel for GPIO %d\n", pwm_gpio_num);
            gpiod_exit();
            return 1;
        }

        pwm_gpio_fd = gpiod_get_file(pwm_channel);
        if (pwm_gpio_fd < 0) {
            fprintf(stderr, "Failed to get file descriptor for PWM channel %d\n", pwm_gpio_num);
            gpiod_exit();
            return 1;
        }
    }

    // Set PWM frequency
    if (gpiod_set_property(pwm_channel, "direction", "output") < 0) {
        fprintf(stderr, "Failed to set PWM direction\n");
        return 1;
    }
    if (gpiod_set_property(pwm_channel, "duty-cycle", &state) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        return 1;
    }
    if (gpiod_set_property(pwm_channel, "frequency", PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return 1;
    }

    // Set PWM state
    for (pwm_gpio_num = 0; pwm_gpio_num < PWM_CHANNELS; pwm_gpio_num++) {
        if (gpiod_set_value(pwm_gpio_num, 1) < 0) {
            fprintf(stderr, "Failed to set PWM GPIO %d to high\n", pwm_gpio_num);
            return 1;
        }
        if (gpiod_set_value(pwm_gpio_num, 0) < 0) {
            fprintf(stderr, "Failed to set PWM GPIO %d to low\n", pwm_gpio_num);
            return 1;
        }
    }

    // Set PWM duty cycle
    while (1) {
        // Check if PWM state is updated
        if (gpiod_get_value(pwm_channel) == 1) {
            state = (state + 1) % 256;
            if (gpiod_set_value(pwm_channel, 1) < 0) {
                fprintf(stderr, "Failed to set PWM GPIO %d to high\n", pwm_gpio_num);
                return 1;
            }
        } else {
            state = (state - 1) % 256;
            if (gpiod_set_value(pwm_channel, 0) < 0) {
                fprintf(stderr, "Failed to set PWM GPIO %d to low\n", pwm_gpio_num);
                return 1;
            }
        }

        // Wait for 0.1 seconds
        sleep(0.1);
    }

    // Release resources
    for (pwm_gpio_num = 0; pwm_gpio_num < PWM_CHANNELS; pwm_gpio_num++) {
        gpiod_set_value(pwm_gpio_num, 0);
    }
    gpiod_exit();

    return 0;
}

