#define BMP280_I2C_ADDR 0x76

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    int ret;

    // Open the I2C bus
    if ((fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set the I2C address of the BMP280
    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) == -1) {
        perror("Error setting I2C address");
        exit(EXIT_FAILURE);
    }

    // Initialize the BMP280
    if (ioctl(fd, BMP280_I2C_RDWR_RESET, 0) == -1) {
        perror("Error initializing BMP280");
        exit(EXIT_FAILURE);
    }

    // Wait for the BMP280 to be ready
    while (1) {
        if (ioctl(fd, BMP280_I2C_RDWR_READ_ID, &data) == -1) {
            perror("Error reading BMP280 ID");
            exit(EXIT_FAILURE);
        }

        if (data.id == 0x77) {
            break;
        }

        usleep(500000); // Wait for 500ms
    }

    // Close the I2C bus
    if (close(fd) == -1) {
        perror("Error closing I2C bus");
        exit(EXIT_FAILURE);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/gpiod.h>

#define PWM_CHANNEL 4
#define PWM_FREQ 50

int main() {
    int fd, status;
    struct gpiod_device *device;
    int pwm_value;

    // Initialize pigpio
    if (gpiod_init() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    // Open GPIO channel
    fd = gpiod_open(PWM_CHANNEL, GPIDX_OUT);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO channel\n");
        gpiod_exit();
        return 1;
    }

    // Set PWM frequency
    status = gpiod_set_property(fd, "format", "int");
    if (status < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency format\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }
    status = gpiod_set_property(fd, "range", "int");
    if (status < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency range\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }
    status = gpiod_set_property(fd, "value", PWM_FREQ);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency value\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set PWM value
    pwm_value = PWM_FREQ / 2; // 50% duty cycle
    status = gpiod_set_value(fd, pwm_value);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to set PWM value\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Print PWM state
    printf("PWM state: %d\n", pwm_value);

    // Wait for user to press a key
    char key;
    while (1) {
        printf("Press 'q' to quit...\n");
        scanf(" %c", &key);
        if (key == 'q') {
            break;
        }
    }

    // Release hardware
    gpiod_release(fd);
    gpiod_exit();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/gpiod.h>

int main() {
    int fd, gpio_num;
    struct gpiod_event_data event_data;
    char state;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Get the BCM GPIO number for GPIO 5, GPIO 6, and GPIO 13
    gpio_num = gpiod_get_bcm_gpio(5);
    if (gpio_num < 0) {
        fprintf(stderr, "Failed to get BCM GPIO number for GPIO 5\n");
        gpiod_exit();
        return 1;
    }

    // Open the digital output GPIO
    fd = gpiod_open(gpiod_get_device(gpio_num), GPIOF_OUT);
    if (fd < 0) {
        fprintf(stderr, "Failed to open digital output GPIO\n");
        gpiod_exit();
        return 1;
    }

    // Set the initial state of the digital output to 0 (low)
    state = 0;
    if (gpiod_set_value(fd, state) < 0) {
        fprintf(stderr, "Failed to set initial state of digital output\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Wait for the digital output to be released
    while (gpiod_get_value(fd) == state) {
        usleep(100000);
    }

    // Set the desired state (1 for high)
    state = 1;
    if (gpiod_set_value(fd, state) < 0) {
        fprintf(stderr, "Failed to set desired state of digital output\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Wait for the digital output to change
    while (gpiod_get_value(fd) == state) {
        usleep(100000);
    }

    // Close the digital output GPIO
    if (gpiod_close(fd) < 0) {
        fprintf(stderr, "Failed to close digital output GPIO\n");
        gpiod_exit();
        return 1;
    }

    // Release libgpiod
    gpiod_exit();

    return 0;
}

