    i2c_data.flags = 0;
    i2c_data.timeout = 100;
    i2c_data.mode = I2C_MODE_I2C;
    i2c_data.addr = I2C_ADDR;
    i2c_data.flags |= I2C_F_RDWR;

    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to set I2C mode");
        exit(EXIT_FAILURE);
    }

