    if (client == NULL) {
        perror("Failed to get I2C client data");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO
    int gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        exit(EXIT_FAILURE);
    }

    struct gpio_mem *gpio_mem = mmap(NULL, PAGE_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, gpio_fd, 0);
    if (gpio_mem == MAP_FAILED) {
        perror("Failed to map GPIO memory");
        exit(EXIT_FAILURE);
    }

    struct gpio_chip *gpio_chip = (struct gpio_chip *)gpio_mem;
    if (gpio_chip == NULL) {
        perror("Failed to get GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpio_chip->base = (struct gpio_regs *)gpio_mem;
    gpio_chip->n_io = GPIO_NUM_GPIO_OUT;

    // Set up PWM
    int pwm_fd = open("/dev/pwmchip0", O_RDWR);
    if (pwm_fd < 0) {
        perror("Failed to open PWM device");
        exit(EXIT_FAILURE);
    }

    struct pwm_mem *pwm_mem = mmap(NULL, PAGE_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, pwm_fd, 0);
    if (pwm_mem == MAP_FAILED) {
        perror("Failed to map PWM memory");
        exit(EXIT_FAILURE);
    }

    struct pwm_chip *pwm_chip = (struct pwm_chip *)pwm_mem;
    if (pwm_chip == NULL) {
        perror("Failed to get PWM chip");
        exit(EXIT_FAILURE);
    }

    pwm_chip->base = (struct pwm_regs *)pwm_mem;
    pwm_chip->n_pwm = 2;

    // Set up MQTT
    mqtt_sock = paho_mqtt_new(&options, MQTT_BROKER, MQTT_TOPIC);
    if (mqtt_sock < 0) {
        perror("Failed to create MQTT client");
        exit(EXIT_FAILURE);
    }

    // Publish sensor readings
    while (1) {
        // Get sensor reading
        // ...

        // Convert reading to string
        char *reading_str = malloc(strlen(reading) + 1);
        snprintf(reading_str, sizeof(reading_str), "%f", reading);

        // Create MQTT message
        message.topic = reading_str;
        message.payload = (void *)reading_str;
        message.qos = 1;
        message.retained = 0;

        // Publish message
        paho_mqtt_publish(mqtt_sock, &message);

        // Release resources
        free(reading_str);
        paho_mqtt_free(mqtt_sock);
    }

    // Clean up GPIO
    close(gpio_fd);
    munmap(gpio_mem, PAGE_SIZE);
    close(mqtt_sock);

    return 0;
}

