#define PWM_CHANNEL_COUNT 4

int main() {
    int pwm_fd, gpio_fd;
    struct gpiod_channel *pwm_channel;
    struct gpiod_event event;
    int error;

    // Initialize pigpio library
    if ((error = gpiod_init()) < 0) {
        fprintf(stderr, "Error initializing pigpio: %d\n", error);
        return 1;
    }

    // Open GPIO and PWM devices
    if ((pwm_fd = gpiod_open(GPIDO_DIR_ACTIVE, GPIDO_TYPE_PWM, 0)) < 0) {
        fprintf(stderr, "Error opening PWM device: %d\n", pwm_fd);
        gpiod_exit(pwm_fd);
        return 1;
    }

    if ((gpio_fd = gpiod_open(GPIDO_DIR_ACTIVE, GPIDO_TYPE_GPIO, 0)) < 0) {
        fprintf(stderr, "Error opening GPIO device: %d\n", gpio_fd);
        gpiod_exit(pwm_fd);
        return 1;
    }

    // Set up PWM channel
    if ((pwm_channel = gpiod_get_channel(pwm_fd, "PWM_OUT0")) < 0) {
        fprintf(stderr, "Error getting PWM channel: %d\n", pwm_channel);
        gpiod_exit(pwm_fd);
        gpiod_close(gpio_fd);
        return 1;
    }

    // Set PWM frequency to 50 Hz
    if (gpiod_set_property(pwm_channel, "frequency", 50) < 0) {
        fprintf(stderr, "Error setting PWM frequency: %d\n", gpiod_get_error(pwm_channel));
        gpiod_close(pwm_channel);
        gpiod_close(gpio_fd);
        gpiod_exit(pwm_fd);
        return 1;
    }

    // Set PWM duty cycle to 50%
    if (gpiod_set_value(pwm_channel, 1) < 0) {
        fprintf(stderr, "Error setting PWM duty cycle: %d\n", gpiod_get_error(pwm_channel));
        gpiod_close(pwm_channel);
        gpiod_close(gpio_fd);
        gpiod_exit(pwm_fd);
        return 1;
    }

    // Set up event for PWM channel
    if ((event.type = GPIDO_EVENT_PWM) == -1) {
        fprintf(stderr, "Error setting up PWM event: %d\n", gpiod_get_error(pwm_channel));
        gpiod_close(pwm_channel);
        gpiod_close(gpio_fd);
        gpiod_exit(pwm_fd);
        return 1;
    }

    event.data.pwm.channel = pwm_channel;
    event.data.pwm.duty_cycle = 50;

    if (gpiod_event_add(pwm_channel, &event) < 0) {
        fprintf(stderr, "Error adding PWM event: %d\n", gpiod_get_error(pwm_channel));
        gpiod_close(pwm_channel);
        gpiod_close(gpio_fd);
        gpiod_exit(pwm_fd);
