    // Start PWM output
    if (gpiod_set_value(pwm_channel, 0) < 0) {
        fprintf(stderr, "Error setting PWM output: %d\n", gpiod_get_error(pwm_channel));
        gpiod_close(pwm_channel);
        gpiod_close(gpio_fd);
        gpiod_exit(pwm_fd);
        return 1;
    }

    // Wait for PWM output to reach 50% duty cycle
    while (gpiod_get_value(pwm_channel) != 1) {
        usleep(500000);
    }

    // Stop PWM output
    if (gpiod_set_value(pwm_channel, 0) < 0) {
        fprintf(stderr, "Error setting PWM output: %d\n", gpiod_get_error(pwm_channel));
        gpiod_close(pwm_channel);
        gpiod_close(gpio_fd);
        gpiod_exit(pwm_fd);
        return 1;
    }

    // Clean up
    gpiod_event_remove(event.data.pwm.channel);
    gpiod_close(pwm_channel);
    gpiod_close(gpio_fd);
    gpiod_exit(pwm_fd);

    return 0;
}

