#define V4L2_DEVICE_PATH "/dev/video0"
#define V4L2_BUF_TYPE V4L2_BUF_TYPE_VIDEO_CAPTURE

int main() {
    int fd, ret;
    struct v4l2_cap_capability cap_capability;
    struct v4l2_stream_id stream_id;
    struct v4l2_stream_parm stream_parm;
    struct v4l2_format format;
    struct v4l2_mmap_parm mmap_parm;
    struct v4l2_mmap_info mmap_info;
    struct v4l2_buffer buffer;
    struct v4l2_plane planes[2];
    char filename[128] = "image.jpg";
    struct v4l2_format format_jpeg;
    struct v4l2_jpeg_compression_parm jpeg_parm;
    struct v4l2_jpeg_compression_parm jpeg_parm_default;

    // Initialize the V4L2 device
    fd = open(V4L2_DEVICE_PATH, O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        perror("Error opening V4L2 device");
        exit(EXIT_FAILURE);
    }

    // Get the capabilities of the camera
    ret = ioctl(fd, VIDIOC_G_CAPABILITY, &cap_capability);
    if (ret < 0) {
        perror("Error getting camera capabilities");
        exit(EXIT_FAILURE);
    }

    // Check if the device is present
    if (cap_capability.capabilities == 0) {
        perror("Device absent");
        exit(EXIT_FAILURE);
    }

    // Set the format to JPEG
    format.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    format.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    format.fmt.pix.width = 640;
    format.fmt.pix.height = 480;

    // Set the JPEG compression parameters
    jpeg_parm_default.jpeg_compression_mode = V4L2_JPEG_COMPRESSION_MODE_FAST;
    jpeg_parm_default.jpeg_quality = 10;
    jpeg_parm.jpeg_compression_mode = V4L2_JPEG_COMPRESSION_MODE_FAST;
    jpeg_parm.jpeg_quality = 10;

    // Set the buffer parameters
    mmap_parm.mmap_ioctl_cmd = V4L2_BUF_IOCTL_CMD_MMAP;
    mmap_parm.mmap_ioctl_flags = V4L2_BUF_IOCTL_FLAG_MMAP_VALID;
    mmap_parm.mmap_size = 4096;
    mmap_parm.mmap_page_size = 4096;
    mmap_parm.plane_mask = 0x1;
    mmap_parm.plane_format = V4L2_PIX_FMT_JPEG;
    mmap_parm.plane_data = planes;

    // Open the camera stream
    ret = ioctl(fd, VIDIOC_STREAMON, &stream_parm);
    if (ret < 0) {
        perror("Error opening camera stream");
        exit(EXIT_FAILURE);
    }

    // Start the camera capture loop
    while (1) {
        // Wait for the next buffer
        ret = ioctl(fd, VIDIOC_G_BUF, &buffer);
        if (ret < 0) {
            perror("Error getting buffer");
            exit(EXIT_FAILURE);
        }

        // Check if the buffer is valid
        if (buffer.length == 0) {
            continue;
        }

        // Capture the image
        ret = ioctl(fd, VIDIOC_S_BUF, &buffer);
        if (ret < 0) {
            perror("Error capturing image");
            exit(EXIT_FAILURE);
        }

        // Save the image to a file
        if (snprintf(filename, sizeof(filename), "image_%d.jpg", buffer.index) < 0) {
            perror("Error formatting filename");
            exit(EXIT_FAILURE);
        }

        // Set the format to JPEG
        format.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        format.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
        format.fmt.pix.width = 640;
        format.fmt.pix.height = 480;

        // Set the JPEG compression parameters
        jpeg_parm.jpeg_compression_mode = V4L2_JPEG_COMPRESSION_MODE_FAST;
        jpeg_parm.jpeg_quality = 10;

        // Set the buffer parameters
        mmap_parm.plane_format = V4L2_PIX_FMT_JPEG;
        mmap_parm.plane_data = planes;

        // Set the buffer to the mmap_parm
        buffer.flags = V4L2_BUF_FLAG_MAPPED;
        buffer.userptr = &mmap_info;
        buffer.length = mmap_info.length;

        // Release the buffer
        ret = ioctl(fd, VIDIOC_QBUF, &buffer);
        if (ret < 0) {
            perror("Error releasing buffer");
            exit(EXIT_FAILURE);
        }

        // Release the camera stream
        ret = ioctl(fd, VIDIO_G_CROP, &stream_id);
        if (ret < 0) {
            perror("Error getting crop");
            exit(EXIT_FAILURE);
        }

        ret = ioctl(fd, VIDIOC_S_CROP, &stream_id);
        if (ret < 0) {
            perror("Error setting crop");
            exit(EXIT_FAILURE);
        }

        // Wait for the next buffer
        ret = ioctl(fd, VIDIOC_STREAMOFF, &stream_parm);
        if (ret < 0) {
            perror("Error closing camera stream");
            exit(EXIT_FAILURE);
        }
    }

    // Release the V4L2 device
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap_capability);
    if (ret < 0) {
        perror("Error querying V4L2 device");
        exit(EXIT_FAILURE);
    }

    if (cap_capability.capabilities & V4L2_CAP_FLAG_CAPTURE) {
        ret = ioctl(fd, VIDIOC_STREAMON, &stream_parm);
        if (ret < 0) {
            perror("Error opening camera stream");
            exit(EXIT_FAILURE);
        }
    }

    close(fd);
    return 0;
}

