        return 1;
    }

    // Open GPIO 18
    if ((fd = pigpio_open(18)) < 0) {
        fprintf(stderr, "Error opening GPIO 18: %d\n", ret);
        return 1;
    }

    // Get the current state of GPIO 18
    if ((ret = pigpio_get_channel_state(fd, 18, &state)) != 0) {
        fprintf(stderr, "Error getting GPIO 18 state: %d\n", ret);
        return 1;
    }

    // Print the current PWM state
    printf("PWM state on GPIO 18: %d\n", state.value);

    // Set the PWM state to 50%
    if ((ret = pigpio_set_duty_cycle(fd, 18, state.value / 2)) < 0) {
        fprintf(stderr, "Error setting PWM duty cycle: %d\n", ret);
        return 1;
    }

    // Wait for the PWM to change
    if ((ret = pigpio_usleep(state.duty_cycle_usec)) < 0) {
        fprintf(stderr, "Error waiting for PWM change: %d\n", ret);
        return 1;
    }

    // Release the GPIO
    if ((ret = pigpio_release(fd)) < 0) {
        fprintf(stderr, "Error releasing GPIO: %d\n", ret);
        return 1;
    }

    // Close the GPIO
    if (pigpio_close(fd) < 0) {
        fprintf(stderr, "Error closing GPIO: %d\n", ret);
        return 1;
    }

    return 0;
}

