#include <sys/gpiod.h>

#define PWM_CHANNEL_17 (17)
#define PWM_CHANNEL_18 (18)
#define PWM_CHANNEL_27 (27)

int main() {
    int fd, error;
    struct gpiod_channel *pwm_channel;
    struct gpiod_event event;
    int state = 0;

    // Initialize pigpio
    if (gpiod_init() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    // Open PWM channel
    fd = gpiod_open(PWM_CHANNEL_17);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open PWM channel 17\n");
        gpiod_exit();
        return 1;
    }

    pwm_channel = gpiod_get_channel(fd);
    if (pwm_channel == NULL) {
        fprintf(stderr, "Error: Failed to get PWM channel 17\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set PWM state
    error = gpiod_event_set_dir(pwm_channel, GPIDO_OUT_HIGH);
    if (error < 0) {
        fprintf(stderr, "Error: Failed to set PWM direction to high\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    error = gpiod_event_set_value(pwm_channel, state);
    if (error < 0) {
        fprintf(stderr, "Error: Failed to set PWM value\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set event to trigger on PWM change
    event.type = GPIDO_EVENT_PWM;
    event.channel = pwm_channel;
    event.value = state;
    event.flags = GPIDO_EVENT_FALLING_EDGE;
    error = gpiod_event_add(fd, &event);
    if (error < 0) {
        fprintf(stderr, "Error: Failed to add PWM event\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set up timer to repeat every 0.5 seconds
    struct itimerspec timer;
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_nsec = 500000;
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_nsec = 500000;

    error = timer_create(ITIMER_REAL, &timer);
    if (error < 0) {
        fprintf(stderr, "Error: Failed to create timer\n");
        gpiod_event_remove(fd, &event);
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set timer to trigger every 0.5 seconds
    error = timer_settime(timer.it_value.tv_sec, timer.it_interval.tv_sec, &timer.it_interval, &timer.it_value);
    if (error < 0) {
        fprintf(stderr, "Error: Failed to set timer interval\n");
        timer_delete(timer.it_value.tv_sec, &timer);
        gpiod_event_remove(fd, &event);
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Infinite loop
    while (1) {
        // Check PWM state
        state = gpiod_event_get_value(pwm_channel);
        if (state == 0) {
            printf("PWM output is set to low\n");
        } else {
            printf("PWM output is set to high\n");
        }

        // Wait for timer to expire
        error = timer_gettime(timer.it_value.tv_sec, &timer.it_value);
        if (error < 0) {
            fprintf(stderr, "Error: Failed to get timer value\n");
            break;
        }

        error = timer_settime(timer.it_value.tv_sec, timer.it_interval.tv_sec, &timer.it_interval, &timer.it_value);
        if (error < 0) {
            fprintf(stderr, "Error: Failed to set timer interval\n");
            break;
        }
    }

    // Clean up
    gpiod_event_remove(fd, &event);
    gpiod_close(fd);
    gpiod_exit();

    return 0;
}

