    struct gpiod_line *dht22_line;
    int dht22_line_state;
    int dht22_reading;
    int dht22_error;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open GPIO device
    if ((dht22_fd = gpiod_open(DHT22_GPIO_PIN, GPID_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to open GPIO device\n");
        gpiod_exit();
        return 1;
    }

    // Get the DHT22 GPIO line
    if ((dht22_dev = gpiod_get_device(DHT22_GPIO_PIN)) == NULL) {
        fprintf(stderr, "Failed to get DHT22 GPIO line\n");
        gpiod_close(dht22_fd);
        gpiod_exit();
        return 1;
    }

    if ((dht22_line = gpiod_get_line(dht22_dev, "dht22_data")) == NULL) {
        fprintf(stderr, "Failed to get DHT22 data line\n");
        gpiod_close(dht22_fd);
        gpiod_exit();
        return 1;
    }

    // Set DHT22 GPIO line to output
    if (gpiod_set_line_property(dht22_line, "direction", "output") < 0) {
        fprintf(stderr, "Failed to set DHT22 data line direction\n");
        gpiod_close(dht22_fd);
        gpiod_exit();
        return 1;
    }

    // Wait for DHT22 to be ready
    if (gpiod_wait_for_line(dht22_line, GPID_LINE_STATE_ACTIVE, NULL) < 0) {
        fprintf(stderr, "Failed to wait for DHT22 to be ready\n");
        gpiod_close(dht22_fd);
        gpiod_exit();
        return 1;
    }

    // Read DHT22 data
    if (gpiod_get_line_value(dht22_line, &dht22_reading) < 0) {
        fprintf(stderr, "Failed to read DHT22 data\n");
        gpiod_close(dht22_fd);
        gpiod_exit();
        return 1;
    }

    // Check if DHT22 data is valid
    if (dht22_reading == 0) {
        fprintf(stderr, "Invalid DHT22 reading\n");
        gpiod_close(dht22_fd);
        gpiod_exit();
        return 1;
    }

    // Report DHT22 state
    printf("DHT22 is connected and ready\n");

    // Release the DHT22 GPIO line
    if (gpiod_release_line(dht22_line) < 0) {
        fprintf(stderr, "Failed to release DHT22 data line\n");
        gpiod_close(dht22_fd);
        gpiod_exit();
        return 1;
    }

    // Clean up
    gpiod_exit();

    return 0;
}

