#define V4L2_DEVICE_PATH "/dev/video0"
#define V4L2_BUF_TYPE V4L2_BUF_TYPE_VIDEO_CAPTURE

int main() {
    int fd, error;
    struct v4l2_cap_capability cap_capability;
    struct v4l2_stream_id stream_id;
    struct v4l2_stream_parm stream_parm;
    struct v4l2_format format;
    struct v4l2_mmap_parm mmap_parm;
    struct v4l2_mmap_info mmap_info;
    struct v4l2_buffer buffer;
    int width, height;
    char *filename;

    // Initialize gpio and pigpio
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize gpio\n");
        return 1;
    }
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open the camera device
    fd = open(V4L2_DEVICE_PATH, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open camera device: %s\n", strerror(errno));
        return 1;
    }

    // Get the camera device capabilities
    error = ioctl(fd, VIDIOC_QUERYCAP, &cap_capability);
    if (error < 0) {
        fprintf(stderr, "Failed to query camera capabilities: %s\n", strerror(errno));
        return 1;
    }

    // Check if the device is a video capture device
    if (cap_capability.capabilities != V4L2_CAP_VIDEO_CAPTURE) {
        fprintf(stderr, "This program only supports video capture devices.\n");
        return 1;
    }

    // Get the stream ID and format
    error = ioctl(fd, VIDIOC_G_STREAM_ID, &stream_id);
    if (error < 0) {
        fprintf(stderr, "Failed to get stream ID: %s\n", strerror(errno));
        return 1;
    }

    error = ioctl(fd, VIDIOC_G_FMT, &format);
    if (error < 0) {
        fprintf(stderr, "Failed to get format: %s\n", strerror(errno));
        return 1;
    }

    // Set the desired image dimensions
    width = format.fmt.pix.width;
    height = format.fmt.pix.height;

    // Allocate memory for the buffer
    buffer.size = width * height * 3;
    buffer.m.mapped = NULL;
    buffer.m.length = buffer.size;
    buffer.userptr = NULL;

    // Allocate memory for the mmap parameters
    mmap_parm.flags = 0;
    mmap_parm.memory = V4L2_MEMORY_MMAP;
    mmap_parm.size = buffer.size;
    mmap_parm.map_flags = 0;
    mmap_parm.fract = 0;
    mmap_parm.reserve = 0;
    mmap_parm.userptr = NULL;

    // Allocate memory for the buffer info
    mmap_info.flags = 0;
    mmap_info.memory = V4L2_MEMORY_MMAP;
    mmap_info.size = buffer.size;
    mmap_info.map_flags = 0;
    mmap_info.userptr = NULL;

    // Allocate memory for the image data
    char *image_data = (char*)malloc(buffer.size);
    if (image_data == NULL) {
        fprintf(stderr, "Failed to allocate memory for image data\n");
        return 1;
    }

    // Capture the image
    error = ioctl(fd, VIDIOC_G_BUF, &buffer);
    if (error < 0) {
        fprintf(stderr, "Failed to get buffer: %s\n", strerror(errno));
        free(image_data);
        return 1;
    }

    // Map the buffer to the image data
    buffer.userptr = mmap(image_data, buffer.size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer.userptr == MAP_FAILED) {
        fprintf(stderr, "Failed to map buffer to image data: %s\n", strerror(errno));
        free(image_data);
        return 1;
    }

    // Set the image dimensions
    buffer.userptr = (char*)buffer.userptr + (width * 3);
    for (int i = 0; i < height; i++) {
        *(buffer.userptr + (width * 3 * i)) = 0;
    }

    // Release the buffer
    error = ioctl(fd, VIDIOC_S_BUF, &buffer);
    if (error < 0) {
        fprintf(stderr, "Failed to release buffer: %s\n", strerror(errno));
        free(image_data);
        return 1;
    }

    // Close the camera device
    error = close(fd);
    if (error < 0) {
        fprintf(stderr, "Failed to close camera device: %s\n", strerror(errno));
        return 1;
    }

    // Release gpio and pigpio
    gpio_deinit();
    pigpio_exit();

    // Save the captured image to a file
    filename = (char*)malloc(100);
    if (filename == NULL) {
        fprintf(stderr, "Failed to allocate memory for filename\n");
        return 1;
    }
    snprintf(filename, 100, "image_%d.jpg", width);

    // Open the file for writing
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for writing: %s\n", strerror(errno));
        free(image_data);
        free(filename);
        return 1;
    }

    // Write the image data to the file
    fwrite(image_data, buffer.size, 1, fp);
    fclose(fp);

    // Release the buffer
    free(image_data);

    // Release the buffer info
    free(mmap_info.userptr);
    free(mmap_parm.userptr);

    // Release the buffer
    free(buffer.userptr);

    return 0;
}

