#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define PWM_CHANNEL_COUNT 4

int main() {
    int pwmChannels[PWM_CHANNEL_COUNT] = {8, 9, 11, 18};
    int pwmFreq = 50; // PWM frequency in Hz
    int pwmResolution = 16; // PWM resolution in bits
    int pwmPeriod = 1 << (pwmResolution - 1); // PWM period in us

    gpio_init();
    gpio_set_mode(pwmChannels, GPIO_OUTPUT);

    while (1) {
        for (int i = 0; i < PWM_CHANNEL_COUNT; i++) {
            gpio_set_pwm_range(pwmChannels[i], 0, pwmPeriod);
            gpio_set_pwm(pwmChannels[i], pwmPeriod / 2, pwmResolution);
            usleep(pwmPeriod / 1000000); // Wait for PWM period
        }

        printf("PWM output values: ");
        for (int i = 0; i < PWM_CHANNEL_COUNT; i++) {
            printf("%d ", gpio_get_pwm(pwmChannels[i]));
        }
        printf("\n");

        usleep(1000); // Wait for 1 second
    }

    gpio_exit();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/v4l2/camera.h>
#include <linux/v4l2/gpib.h>

#define V4L2_DEVICE_PATH "/dev/video0"
#define FILE_NAME "image.jpg"

int main() {
    int fd, error;
    struct v4l2_cap_capability cap_capability;
    struct v4l2_stream_id stream_id;
    struct v4l2_stream_parm stream_parm;
    struct v4l2_format format;
    struct v4l2_mmap_parm mmap_parm;
    struct v4l2_mmap_info mmap_info;
    struct v4l2_buffer buffer;
    char *filename;

    // Initialize the V4L2 device
    fd = open(V4L2_DEVICE_PATH, O_RDWR);
    if (fd < 0) {
        perror("Error opening V4L2 device");
        exit(EXIT_FAILURE);
    }

    // Check if the device is present
    error = ioctl(fd, VIDIOC_QUERYCAP, &cap_capability);
    if (error < 0) {
        if (errno == ENODEV) {
            perror("Device not present");
            exit(EXIT_FAILURE);
        } else {
            perror("Error checking device presence");
            exit(EXIT_FAILURE);
        }
    }

    // Set up the camera parameters
    memset(&stream_parm, 0, sizeof(stream_parm));
    stream_parm.type = V4L2_STREAM_TYPE_VIDEO_CAPTURE;
    stream_parm.bufmgr.type = V4L2_BUFMM_TYPE_REGULAR;
    stream_parm.bufmgr.buf_size = 1024 * 1024;
    stream_parm.bufmgr.num_buffers = 1;
    stream_parm.bufmgr.buf_size = 1024 * 1024;
    stream_parm.bufmgr.flags = V4L2_BUF_FLAG_KEY_PRESENT;
    stream_parm.bufmgr.auto_trigger = 1;
    stream_parm.bufmgr.timeout = 0;
    stream_parm.bufmgr.async = 1;

    // Set up the format
    memset(&format, 0, sizeof(format));
    format.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    format.fmt.pix.width = 640;
    format.fmt.pix.height = 480;
    format.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    format.fmt.pix.field = V4L2_FIELD_INTERLACED;

    // Set up the memory mapping
    memset(&mmap_parm, 0, sizeof(mmap_parm));
    mmap_parm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    mmap_parm.mmap.flags = V4L2_MMAP_USERPTR | V4L2_MMAP_READ | V4L2_MMAP_WRITE;
    mmap_parm.mmap.userptr = NULL;
    mmap_parm.mmap.length = 1024 * 1024;
    mmap_parm.mmap.offset = 0;

    // Open the camera device
    error = ioctl(fd, VIDIOC_STREAMON, &stream_parm);
    if (error < 0) {
        perror("Error enabling camera");
        exit(EXIT_FAILURE);
    }

    // Capture the image
    filename = (char*)malloc(strlen(FILE_NAME) + 1);
    snprintf(filename, strlen(FILE_NAME) + 1, "%s", FILE_NAME);

    while (1) {
        // Wait for the next buffer
        error = ioctl(fd, VIDIOC_DQBUF, &buffer);
        if (error < 0) {
            perror("Error waiting for buffer");
            exit(EXIT_FAILURE);
        }

        // Read the image data
        error = read(buffer.m.fd, buffer.data, buffer.m.length);
        if (error < 0) {
            perror("Error reading image data");
            exit(EXIT_FAILURE);
        }

        // Save the image to a file
        if (write(1, buffer.data, buffer.m.length) < 0) {
            perror("Error writing image data to file");
            exit(EXIT_FAILURE);
        }

        // Release the buffer
        error = ioctl(buffer.m.fd, VIDIOC_DQBUF, &buffer);
        if (error < 0) {
            perror("Error releasing buffer");
            exit(EXIT_FAILURE);
        }
    }

    // Release the camera device
    error = ioctl(fd, VIDIOC_STREAMOFF, &stream_parm);
