#include <linux/i2c.h>
#include <linux/i2c-gpio.h>

#define I2C_DEVICE_PATH "/dev/i2c-1"
#define I2C_ADDR 0x20

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg[2];
    int ret;

    // Initialize I2C device
    fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C address");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C gpio
    if (ioctl(fd, I2C_FUNCS, I2C_FUNC_I2C) < 0) {
        perror("Error setting I2C gpio");
        exit(EXIT_FAILURE);
    }

    // Set up the I2C gpio pins
    if (gpio_request_from_mem(I2C_ADDR, I2C_GPIO_P0_0, 1) < 0) {
        perror("Error requesting GPIO pins");
        exit(EXIT_FAILURE);
    }

    // Initialize the PCF8574
    if (pcf8574_init() < 0) {
        perror("Error initializing PCF8574");
        exit(EXIT_FAILURE);
    }

    // Display PCF8574 readings
    while (1) {
        // Read data from the PCF8574
        ret = pcf8574_read_data(0, &data);
        if (ret < 0) {
            perror("Error reading PCF8574 data");
            exit(EXIT_FAILURE);
        }

        // Print the data
        printf("PCF8574 Data: %d, %d, %d, %d, %d, %d\n", data.data[0], data.data[1], data.data[2], data.data[3], data.data[4], data.data[5]);

        // Wait for a short period before displaying the next reading
        sleep(1);
    }

    // Release resources
    gpio_release_from_mem(I2C_ADDR, I2C_GPIO_P0_0);
    pcf8574_deinit();
    close(fd);

    return 0;
}

