        fprintf(stderr, "Failed to open device\n");
        gpiod_exit();
        return 1;
    }

    // Get the device structure
    device = gpiod_get_device(fd);

    // Check if the device is available
    if (device == NULL) {
        fprintf(stderr, "Device not available\n");
        gpiod_exit();
        return 1;
    }

    // Set the digital output to a known state (e.g., high)
    if (gpiod_set_value(device, GPIDO_LINE_GPIO23, GPIDO_LINE_HIGH) < 0) {
        fprintf(stderr, "Failed to set digital output to high\n");
        gpiod_exit();
        return 1;
    }

    // Check if the device is responsive
    if (gpiod_get_value(device, GPIDO_LINE_GPIO23) != GPIDO_LINE_HIGH) {
        fprintf(stderr, "Device not responsive\n");
        gpiod_exit();
        return 1;
    }

    // Repeat the process every 5 seconds
    while (1) {
        // Check if the program is interrupted
        if (interrupt_received()) {
            fprintf(stderr, "Program interrupted\n");
            gpiod_exit();
            return 1;
        }

        // Check the state of the digital output
        if (gpiod_get_value(device, GPIDO_LINE_GPIO23) != GPIDO_LINE_HIGH) {
            printf("Digital output is set to %s\n", gpiod_line_to_name(device, GPIDO_LINE_GPIO23));
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Release the device and libgpiod resources
    gpiod_exit();

    return 0;
}

