    if ((fd = open(I2C_DEVICE_PATH, O_RDWR)) < 0) {
        perror("Error opening I2C device");
        exit(EXIT_FAILURE);
    }

    // Set up I2C bus for read and write
    if (ioctl(fd, I2C_SLAVE, I2C_BUS_NUM) < 0) {
        perror("Error setting I2C bus");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C gpio
    if (ioctl(fd, I2C_FUNCS, I2C_FUNC_I2C) < 0) {
        perror("Error setting I2C gpio");
        exit(EXIT_FAILURE);
    }

    // Initialize MPU6050
    if (mpu6050_init() < 0) {
        perror("Error initializing MPU6050");
        exit(EXIT_FAILURE);
    }

    // Repeat once every 0.1 seconds
    while (1) {
        // Read data from MPU6050
        if (mpu6050_read_data(&data) < 0) {
            perror("Error reading data from MPU6050");
            exit(EXIT_FAILURE);
        }

        // Print the reading to standard output
        printf("MPU6050 reading: x=%d y=%d z=%d\n", data.x, data.y, data.z);

        // Wait for 0.1 seconds
        usleep(100000);
    }

    // Release resources
    mpu6050_cleanup();
    close(fd);

    return 0;
}

