        gpiod_get_line_config(16, &event.line_config) < 0 ||
        gpiod_get_line_config(19, &event.line_config) < 0 ||
        gpiod_get_line_config(20, &event.line_config) < 0 ||
        gpiod_get_line_config(23, &event.line_config) < 0 ||
        gpiod_get_line_config(24, &event.line_config) < 0 ||
        gpiod_get_line_config(25, &event.line_config) < 0 ||
        gpiod_get_line_config(26, &event.line_config) < 0) {
        fprintf(stderr, "Failed to get GPIO line configuration\n");
        gpiod_exit();
        return 1;
    }

    // Open the GPIO device
    fd = gpiod_get_device("/dev/gpiochip0");
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO device\n");
        gpiod_exit();
        return 1;
    }

    // Set the GPIO pin as an output
    gpio_num = 5;
    if (gpiod_set_line(fd, gpio_num, GPIGPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin as output\n");
        gpiod_exit();
        return 1;
    }

    // Set the GPIO pin state to 1 (high)
    state = 1;
    if (gpiod_set_line(fd, gpio_num, state) < 0) {
        fprintf(stderr, "Failed to set GPIO pin state\n");
        gpiod_exit();
        return 1;
    }

    // Wait for the GPIO pin to change state
    while (1) {
        if (gpiod_get_line(fd, gpio_num) == state) {
