#define PWM_CHANNELS 4

int main() {
    int fd, pwm_fd;
    struct gpiod_device *device;
    struct gpiod_line *pwm_line;
    int error;

    // Initialize pigpio library
    if (gpio_init() < 0) {
        fprintf(stderr, "Error initializing pigpio library\n");
        return 1;
    }

    // Open GPIO file descriptors
    fd = open("/dev/pigpio", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening pigpio device file\n");
        return 1;
    }

    pwm_fd = open("/dev/pigpio_pwm", O_RDWR);
    if (pwm_fd < 0) {
        fprintf(stderr, "Error opening pigpio PWM file\n");
        return 1;
    }

    // Open PWM channels
    for (int i = 0; i < PWM_CHANNELS; i++) {
        device = gpiod_get_device("/dev/pigpio");
        if (!device) {
            fprintf(stderr, "Error getting pigpio device\n");
            return 1;
        }

        pwm_line = gpiod_get_line("/dev/pigpio", device, "PWM");
        if (!pwm_line) {
            fprintf(stderr, "Error getting PWM line\n");
            return 1;
        }

        if (gpiod_set_direction(pwm_line, GPIDO_OUTPUT) < 0) {
            fprintf(stderr, "Error setting PWM direction\n");
            return 1;
        }

        if (gpiod_set_value(pwm_line, 0) < 0) {
            fprintf(stderr, "Error setting PWM value\n");
            return 1;
        }

        gpiod_release(pwm_line);
    }

    // Check for device absence
    if (gpiod_get_state("/dev/pigpio") == -1) {
        fprintf(stderr, "Device absent\n");
        return 1;
    }

    // Close all file descriptors
    close(fd);
    close(pwm_fd);

    // Release pigpio resources
    gpio_exit();

    return 0;
}

