int main() {
    int fd, ret;
    struct gpiod_device *device;
    int state;

    // Initialize libgpiod
    if ((ret = gpiod_init()) != 0) {
        fprintf(stderr, "Error initializing libgpiod: %s\n", gpiod_strerror(ret));
        return 1;
    }

    // Open GPIO 2 and GPIO 3
    if ((fd = gpiod_open(GPIDO_DIR_INPUT, GPIDO_PATH_GPIO2)) < 0) {
        fprintf(stderr, "Error opening GPIO 2: %s\n", gpiod_strerror(ret));
        gpiod_exit();
        return 1;
    }

    if ((device = gpiod_get_device(fd)) == NULL) {
        fprintf(stderr, "Error getting device for GPIO 2: %s\n", gpiod_strerror(ret));
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set the GPIO as an output
    if ((ret = gpiod_set_direction(device, GPIDO_DIR_OUTPUT)) < 0) {
        fprintf(stderr, "Error setting GPIO direction for GPIO 2: %s\n", gpiod_strerror(ret));
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set the GPIO state to 0 (low)
    if ((ret = gpiod_set(device, 0)) < 0) {
        fprintf(stderr, "Error setting GPIO state for GPIO 2: %s\n", gpiod_strerror(ret));
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Repeat the process once every 1 second
    while (1) {
        // Read the GPIO state
        if ((ret = gpiod_get(device, &state)) < 0) {
            fprintf(stderr, "Error reading GPIO state for GPIO 2: %s\n", gpiod_strerror(ret));
            gpiod_close(fd);
            gpiod_exit();
            return 1;
        }

        // Print the state
        printf("GPIO 2 (GPIO 3) state: %d\n", state);

        // Wait for 1 second
        sleep(1);
    }

    // Release the GPIO resources
    gpiod_close(fd);
    gpiod_exit();

    return 0;
}

