    direction = GPIDIO_DIR_OUT;
    ret = gpiod_set_direction(fd, "gpio17", direction);
    if (ret < 0) {
        fprintf(stderr, "Error: Unable to set direction\n");
        gpiod_close(fd);
        return 1;
    }

    // Set the value of the GPIO pin
    value = 1;
    ret = gpiod_set(fd, "gpio17", value, NULL);
    if (ret < 0) {
        fprintf(stderr, "Error: Unable to set value\n");
        gpiod_close(fd);
        return 1;
    }

    // Monitor the GPIO pin
    while (1) {
        ret = gpiod_get_value(fd, "gpio17", &value);
        if (ret < 0) {
            fprintf(stderr, "Error: Unable to get value\n");
            break;
        }

