        return 1;
    }

    // Open GPIO 18 and GPIO 27
    if ((fd = gpiod_open(GPIDX_GPIO, 18)) < 0) {
        fprintf(stderr, "Failed to open GPIO 18\n");
        gpiod_exit();
        return 1;
    }

    if ((device = gpiod_get_device(fd)) == NULL) {
        fprintf(stderr, "Failed to get device for GPIO 18\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set the GPIO as an output
    if (gpiod_set_direction(device, GPIDX_GPIO, GPIDX_OUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 18 as an output\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set the GPIO state to 1 (digital output)
    if (gpiod_set_value(device, GPIDX_GPIO, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO 18 to 1\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
