    line_config.line = 27;
    line_config.direction = GPIDIO_DIRECTION_OUT;
    ret = gpiod_set_line_config(fd, &line_config);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 27 as a digital output.\n");
        return 1;
    }

    // Set up the event configuration
    event_config.type = GPIDIO_EVENT_TYPE_RISING_EDGE;
    event_config.edge_mask = GPIDIO_EDGE_RISING;
    event_config.callback = GPIO_EVENT_CALLBACK_DIGITAL;
    event_config.callback_arg = &gpio_callback;

    // Register the event
    ret = gpiod_event_register(fd, &event_config);
    if (ret < 0) {
        fprintf(stderr, "Failed to register GPIO event.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read the state of GPIO 27
        ret = gpiod_get_line_state(fd, 27, &state);
        if (ret < 0) {
            fprintf(stderr, "Failed to read GPIO 27 state.\n");
            return 1;
        }

        // Validate the read state
        if (state != GPIDIO_LINE_STATE_LOW) {
            fprintf(stderr, "Invalid state read from GPIO 27.\n");
            continue;
        }

        // Print the state
        printf("GPIO 27 state: Low\n");

        // Wait for 2 seconds
        sleep(2);
    }

    // Release the GPIO resources
    gpiod_event_unregister(fd, &event_config);
    gpiod_set_line_config(fd, &line_config);
    gpiod_close(fd);

    return 0;
}

