#include <sys/gpiod.h>

int main() {
    int fd;
    struct gpiod_info info;
    int state;

    // Initialize the GPIO device
    fd = gpiod_get_fd("/dev/gpiochip0");
    if (fd < 0) {
        fprintf(stderr, "Failed to get GPIO device file descriptor: %s\n", strerror(errno));
        return 1;
    }

    // Check if the GPIO device is available
    if (gpiod_get_state(fd, &info) < 0) {
        fprintf(stderr, "Failed to get GPIO state: %s\n", strerror(errno));
        gpiod_close(fd);
        return 1;
    }

    // Check if the GPIO is available
    if (info.state == GPIGPIO_STATE_LOW) {
        fprintf(stderr, "GPIO18 is already set to low\n");
        gpiod_close(fd);
        return 1;
    }

    // Set GPIO18 to high
    state = 1;
    if (gpiod_set_value(fd, "/sys/class/gpio/gpio18/value", state) < 0) {
        fprintf(stderr, "Failed to set GPIO18 to high: %s\n", strerror(errno));
        gpiod_close(fd);
        return 1;
    }

    // Repeat every 5 seconds
    while (1) {
        // Check if the GPIO state is still high
        if (gpiod_get_value(fd, "/sys/class/gpio/gpio18/value") == state) {
            printf("GPIO18 is already set to high\n");
            continue;
        }

        // Read the GPIO state
        if (gpiod_get_state(fd, &info) < 0) {
            fprintf(stderr, "Failed to get GPIO state: %s\n", strerror(errno));
            gpiod_close(fd);
            return 1;
        }

        // Check if the reading is valid
        if (info.state == GPIGPIO_STATE_LOW) {
            fprintf(stderr, "Failed to read the GPIO state: %s\n", strerror(errno));
            gpiod_close(fd);
            return 1;
        }

        // Print the current state of GPIO18
        printf("GPIO18 is now set to %d\n", state);

        // Wait for 5 seconds
        sleep(5);
    }

    // Release the GPIO device
    gpiod_close(fd);

    return 0;
}

