#define GPIO_4  4
#define I2C_BUS "/dev/i2c-1"

int main() {
    int rc;
    int i;
    int device_present = 0;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_rdwr_ioctl_data *data_ptr;

    // Initialize GPIO and I2C
    if (gpio_request_from_mem(GPIO_4, 1) < 0) {
        fprintf(stderr, "Failed to request GPIO 4\n");
        return 1;
    }

    if (i2c_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        gpio_free(GPIO_4);
        return 1;
    }

    // Open I2C bus
    if ((rc = i2c_open(I2C_BUS, I2C_CLIENT_IOCTL)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        i2c_exit();
        gpio_free(GPIO_4);
        return 1;
    }

    // Check for device presence
    if (ds18b20_search(I2C_BUS) < 0) {
        fprintf(stderr, "Failed to find DS18B20 device\n");
        i2c_exit();
        gpio_free(GPIO_4);
        return 1;
    }

    // Print initial reading
    printf("Initial reading: %d\n", ds18b20_read_temp_byte(I2C_BUS));

    // Run the readings
    for (i = 0; i < 3; i++) {
        // Wait for 5 seconds
        sleep(5);

        // Check for device presence
        if (ds18b20_search(I2C_BUS) < 0) {
            fprintf(stderr, "Device not present\n");
            break;
        }

        // Print current reading
        printf("Current reading: %d\n", ds18b20_read_temp_byte(I2C_BUS));
    }

    // Release resources
    i2c_exit();
    gpio_free(GPIO_4);

    return 0;
}

