#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/gpiod.h>

#define SENSOR_PIN 18
#define ECHO_PIN 23
#define TRIG_PIN 24

int main() {
    int fd, gpio_direction, gpio_value;
    struct gpiod_event event;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open GPIO pins
    fd = gpiod_get_direction(SENSOR_PIN);
    if (fd < 0) {
        fprintf(stderr, "Failed to get direction for GPIO %d\n", SENSOR_PIN);
        return 1;
    }
    gpio_direction = gpiod_get_state(fd);
    if (gpio_direction & (1 << SENSOR_PIN)) {
        fprintf(stderr, "Sensor pin %d is already set to high\n", SENSOR_PIN);
        return 1;
    }

    gpio_direction |= (1 << SENSOR_PIN);
    if (gpiod_set_direction(fd, gpio_direction) < 0) {
        fprintf(stderr, "Failed to set direction for GPIO %d\n", SENSOR_PIN);
        return 1;
    }

    fd = gpiod_get_value(ECHO_PIN);
    if (fd < 0) {
        fprintf(stderr, "Failed to get value for GPIO %d\n", ECHO_PIN);
        return 1;
    }
    gpio_value = gpiod_get_value(fd);
    if (gpio_value & (1 << ECHO_PIN)) {
        fprintf(stderr, "Echo pin %d is already set to high\n", ECHO_PIN);
        return 1;
    }

    gpio_value |= (1 << ECHO_PIN);
    if (gpiod_set_value(fd, gpio_value) < 0) {
        fprintf(stderr, "Failed to set value for GPIO %d\n", ECHO_PIN);
        return 1;
    }

    // Set up the HC-SR04 sensor
    event.type = GPIGPIO_EVENT_GPIO;
    event.gpio_id = SENSOR_PIN;
    event.event_type = GPIGPIO_EVENT_GPIO_EDGE_FALLING;
    event.gpio_edge_type = GPIGPIO_EDGE_FALLING;
    event.gpio_direction = gpio_direction;
    event.gpio_value = gpio_value;

    if (gpiod_event_register(fd, &event) < 0) {
        fprintf(stderr, "Failed to register event for GPIO %d\n", SENSOR_PIN);
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for the sensor to trigger
        if (gpiod_event_wait(fd, &event) < 0) {
            fprintf(stderr, "Failed to wait for sensor event\n");
            return 1;
        }

        // Check if the sensor has triggered
        if (event.gpio_value & (1 << SENSOR_PIN)) {
            printf("Sensor triggered at %d cm\n", (event.gpio_value & 0xFFFF) / 10);
        }

        // Wait for the sensor to return a reading
        if (gpiod_event_wait(fd, &event) < 0) {
            fprintf(stderr, "Failed to wait for sensor event\n");
            return 1;
        }

        // Check if the sensor has returned a reading
        if (event.gpio_value & (1 << SENSOR_PIN)) {
            printf("Sensor returned a reading at %d cm\n", (event.gpio_value & 0xFFFF) / 10);
        }

        // Release the sensor
        gpio_value = gpiod_get_value(ECHO_PIN);
        if (gpio_value & (1 << ECHO_PIN)) {
            gpio_value &= ~(1 << ECHO_PIN);
            if (gpiod_set_value(fd, gpio_value) < 0) {
                fprintf(stderr, "Failed to release echo pin\n");
                return 1;
            }
        }

        gpio_value = gpiod_get_value(SENSOR_PIN);
        if (gpio_value & (1 << SENSOR_PIN)) {
            gpio_value &= ~(1 << SENSOR_PIN);
            if (gpiod_set_value(fd, gpio_value) < 0) {
                fprintf(stderr, "Failed to release sensor pin\n");
                return 1;
            }
        }
    }

    // Clean up
    gpiod_event_unregister(fd, &event);
    gpiod_release(fd);
    gpiod_exit();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/gpiod.h>

int main() {
    int fd, state;
    struct gpiod_line_config line_config;
    char line_name[] = "/sys/class/gpio/gpio17";

    // Initialize the GPIO line
    fd = gpiod_get_line(line_name);
    if (fd < 0) {
        fprintf(stderr, "Failed to get line %s: %s\n", line_name, strerror(errno));
        return 1;
    }

    // Configure the GPIO line as an output
    line_config.direction = GPIDIO_DIRECTION_OUT;
    line_config.edge = GPIDIO_EDGE_NONE;
    line_config.type = GPIDIO_TYPE_DIGITAL;
    line_config.active_low = 0;

    if (gpiod_set_line_config(fd, &line_config) < 0) {
        fprintf(stderr, "Failed to set line %s configuration: %s\n", line_name, strerror(errno));
        gpiod_close(fd);
        return 1;
    }

    // Apply a state to the GPIO line
    state = 1;
    if (gpiod_line_write(fd, state) < 0) {
        fprintf(stderr, "Failed to set state on line %s: %s\n", line_name, strerror(errno));
        gpiod_close(fd);
        return 1;
    }

    // Print the initial state
    printf("Initial state: %d\n", state);

    // Execute 10 cycles
    for (int i = 0; i < 10; i++) {
        state = !state;
        if (gpiod_line_write(fd, state) < 0) {
            fprintf(stderr, "Failed to set state on line %s: %s\n", line_name, strerror(errno));
            break;
        }
        printf("State after cycle %d: %d\n", i+1, state);
    }

    // Release the GPIO line
    if (gpiod_line_unexport(fd) < 0) {
        fprintf(stderr, "Failed to unexport line %s: %s\n", line_name, strerror(errno));
        gpiod_close(fd);
        return 1;
    }

    // Close the GPIO line
    gpiod_close(fd);

    return 0;
}

