        fprintf(stderr, "Failed to initialize gpio\n");
        return 1;
    }

    // Open GPIO device
    if ((fd = gpiod_open(GPIDO_DIR_OUT, GPIDO_MODE_OUTPUT, 0)) < 0) {
        fprintf(stderr, "Failed to open GPIO device\n");
        gpiod_exit();
        return 1;
    }

    // Get the device structure
    device = gpiod_get_device(fd);

    // Set the direction of GPIO 2 to output
    if (gpiod_set_direction(device, GPIDO_DIR_OUT) < 0) {
        fprintf(stderr, "Failed to set direction to output\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set the value of GPIO 2 to 1 (digital output high)
    if (gpiod_set_value(device, 1) < 0) {
        fprintf(stderr, "Failed to set value to 1\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Repeat the following steps every 5 seconds
    while (1) {
        // Check if the value is 1 (digital output high)
        if (gpiod_get_value(device) == 1) {
            printf("Digital output is already high\n");
