    if ((ret = gpiod_init()) != 0) {
        fprintf(stderr, "Error initializing libgpiod: %d\n", ret);
        return 1;
    }

    // Open GPIO device
    if ((fd = gpiod_open(GPIO_OUTPUT_PIN)) < 0) {
        fprintf(stderr, "Error opening GPIO device: %d\n", fd);
        gpiod_exit();
        return 1;
    }

    // Open PWM lines
    if ((device = gpiod_get_device(GPIO_OUTPUT_PIN)) == NULL) {
        fprintf(stderr, "Error getting device for GPIO %d\n", GPIO_OUTPUT_PIN);
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }
    if ((line = gpiod_get_line(device, GPIO_PWM_PIN)) == NULL) {
        fprintf(stderr, "Error getting line for GPIO %d\n", GPIO_PWM_PIN);
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }
    if ((line = gpiod_get_line(device, GPIO_PWM_PIN_2)) == NULL) {
        fprintf(stderr, "Error getting line for GPIO %d\n", GPIO_PWM_PIN_2);
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set initial state
    state = gpiod_get_level(line);
    printf("Initial state: %d\n", state);

    // Loop 5 times
    for (int i = 0; i < 5; i++) {
        // Set the output state
        if (gpiod_set_value(line, state) < 0) {
