#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/gpiod.h>

#define GPIO_DIR_OUT 0x0001
#define GPIO_OUTPUT_SET 0x0002
#define GPIO_OUTPUT_CLEAR 0x0004

int main() {
    int fd, gpio_num;
    struct gpiod_line_config line_config;
    char line_name[32];

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Check for GPIO device absence
    if (gpiod_get_device_count() == 0) {
        fprintf(stderr, "Device absent, exiting\n");
        gpiod_exit();
        return 1;
    }

    // Loop to control GPIO pins
    for (int i = 0; i < 100; i++) {
        // Get the GPIO number for the current iteration
        gpio_num = (i + 4) % 27;

        // Set the GPIO direction to output
        line_config.line_name = line_name;
        line_config.line_config = GPIO_DIR_OUT;
        line_config.flags = GPIO_OUTPUT_SET;

        // Open the GPIO line
        fd = gpiod_get_line(gpio_num);
        if (fd < 0) {
            fprintf(stderr, "Failed to open GPIO line %d\n", gpio_num);
            continue;
        }

        // Apply the desired state to the GPIO line
        if (gpiod_set_line_config(fd, &line_config) < 0) {
            fprintf(stderr, "Failed to set GPIO line %d to output\n", gpio_num);
            continue;
        }

        // Print the current state of the GPIO line
        char state;
        if (gpiod_get_line_level(fd, &state) < 0) {
            fprintf(stderr, "Failed to read GPIO line %d\n", gpio_num);
            continue;
        }
        printf("GPIO %d: %c\n", gpio_num, state);

        // Wait for 0.5 seconds
        sleep(0.5);

        // Clear the GPIO line
        line_config.line_config = GPIO_OUTPUT_CLEAR;
        if (gpiod_set_line_config(fd, &line_config) < 0) {
            fprintf(stderr, "Failed to set GPIO line %d to output\n", gpio_num);
            continue;
        }

        // Print the final state of the GPIO line
        char final_state;
        if (gpiod_get_line_level(fd, &final_state) < 0) {
            fprintf(stderr, "Failed to read GPIO line %d\n", gpio_num);
            continue;
        }
        printf("GPIO %d: %c\n", gpio_num, final_state);

        // Close the GPIO line
        if (gpiod_release_line(fd) < 0) {
            fprintf(stderr, "Failed to release GPIO line %d\n", gpio_num);
            continue;
        }
    }

    // Release all resources
    gpiod_exit();

    return 0;
}

