        fprintf(stderr, "Failed to open GPIO file descriptor\n");
        gpiod_close(pwm_fd);
        gpiod_exit();
        return 1;
    }

    // Set PWM frequency to 50 Hz
    if (gpiod_set_property(pwm_fd, "duty_cycle", "50") < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpiod_close(pwm_fd);
        gpiod_close(gpio_fd);
        gpiod_exit();
        return 1;
    }

    // Set PWM duty cycle to 50%
    if (gpiod_set_property(pwm_fd, "duty_cycle", "50") < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        gpiod_close(pwm_fd);
        gpiod_close(gpio_fd);
        gpiod_exit();
        return 1;
    }

    // Set GPIO direction to output
    if (gpiod_set_direction(gpio_fd, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO direction to output\n");
        gpiod_close(pwm_fd);
        gpiod_close(gpio_fd);
        gpiod_exit();
        return 1;
    }

    // Loop to drive PWM and report state
    while (1) {
        // Get current PWM state
        if (gpiod_get_property(pwm_fd, "duty_cycle", &state) < 0) {
            fprintf(stderr, "Failed to get PWM duty cycle\n");
            gpiod_close(pwm_fd);
            gpiod_close(gpio_fd);
            gpiod_exit();
            return 1;
        }

        // Print PWM state
        printf("PWM %d: %d%%\n", i + 1, (int)state.value);

        // Wait for 1 second
        sleep(1);
    }

    // Release resources
    gpiod_exit();
    gpiod_close(pwm_fd);
    gpiod_close(gpio_fd);

    return 0;
}

