int main() {
    int fd, gpio_num;
    struct gpiod_event event;
    char state;

    // Initialize the GPIO device
    fd = gpiod_get_fd("/dev/gpiochip0");
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO device: %s\n", strerror(errno));
        return 1;
    }

    // Set up the GPIO pin
    gpio_num = 17; // BCM GPIO numbering
    state = gpiod_get_level(fd, gpio_num);
    if (state == -1) {
        fprintf(stderr, "Failed to get GPIO state: %s\n", strerror(errno));
        gpiod_close(fd);
        return 1;
    }

    // Set the GPIO pin as an output
    if (gpiod_set_direction(fd, gpio_num, GPIDIO_DIR_OUT) < 0) {
        fprintf(stderr, "Failed to set GPIO direction: %s\n", strerror(errno));
        gpiod_close(fd);
        return 1;
    }

    // Set the GPIO pin state
    if (gpiod_set_value(fd, gpio_num, state == 0) < 0) {
        fprintf(stderr, "Failed to set GPIO state: %s\n", strerror(errno));
        gpiod_close(fd);
        return 1;
    }

    // Repeat every 0.1 seconds
    while (1) {
        // Get the current GPIO state
        state = gpiod_get_level(fd, gpio_num);
        if (state == -1) {
            fprintf(stderr, "Failed to get GPIO state: %s\n", strerror(errno));
            break;
        }

        // Print the current state
        printf("GPIO %d: %d\n", gpio_num, state);

        // Wait for 0.1 seconds
        sleep(0.1);
    }

    // Release the GPIO device
    gpiod_release(fd);

    return 0;
}

