int main() {
    int file;
    struct gpiod_event_state state;
    int ret;

    // Initialize the GPIO file
    file = gpiod_get_file();
    if (file < 0) {
        fprintf(stderr, "Failed to get GPIO file: %s\n", strerror(errno));
        return 1;
    }

    // Set the GPIO 27 as an output
    ret = gpiod_set_direction(file, GPIO_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO direction: %s\n", strerror(errno));
        gpiod_close(file);
        return 1;
    }

    // Set the initial state of the GPIO 27 to 0
    state.value = 0;
    ret = gpiod_set_value(file, state);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO value: %s\n", strerror(errno));
        gpiod_close(file);
        return 1;
    }

    // Repeat every 0.1 seconds
    while (1) {
        // Wait for the next event
        ret = gpiod_event_wait(file, &state);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for event: %s\n", strerror(errno));
            gpiod_close(file);
            return 1;
        }

        // Check if the state of GPIO 27 has changed
        if (state.value != 0) {
            printf("GPIO 27 state changed to 1\n");
        }

        // Release the GPIO 27
        ret = gpiod_set_value(file, state);
        if (ret < 0) {
            fprintf(stderr, "Failed to release GPIO value: %s\n", strerror(errno));
            gpiod_close(file);
            return 1;
        }

        // Wait for 0.1 seconds
        sleep(0.1);
    }

    // Release the GPIO file and close the program
    gpiod_close(file);
    return 0;
}

