        return 1;
    }

    // Configure the line
    line_config.type = GPIDX_OUT;
    line_config.direction = GPIDX_OUT_OUTPUT;
    line_config.state = GPIDX_LOW;

    ret = gpiod_set_line_config(fd, &line_config);
    if (ret < 0) {
        fprintf(stderr, "Failed to set line %d configuration: %s\n", 18, strerror(ret));
        gpiod_close(fd);
        return 1;
    }

    // Set the initial state
    ret = gpiod_set(fd, line_config.index, line_config.state);
    if (ret < 0) {
        fprintf(stderr, "Failed to set line %d state: %s\n", 18, strerror(ret));
        gpiod_close(fd);
        return 1;
    }

    // Repeat every 2 seconds
    while (1) {
        // Check if the line is in the desired state
        ret = gpiod_get(fd, line_config.index, &line_config.state);
        if (ret < 0) {
            fprintf(stderr, "Failed to get line %d state: %s\n", 18, strerror(ret));
            continue;
        }

        if (line_config.state == GPIDX_LOW) {
            printf("Digital output is set to LOW\n");
        } else {
            printf("Digital output is set to HIGH\n");
        }

        // Wait for 2 seconds
        sleep(2);
    }

    // Release the GPIO line
    ret = gpiod_release(fd);
    if (ret < 0) {
        fprintf(stderr, "Failed to release line %d: %s\n", 18, strerror(ret));
    }

