#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/gpiod.h>

int main() {
    int fd, gpio_num;
    struct gpiod_line_config line_config;
    char line_state;

    // Initialize the GPIO file descriptor
    fd = gpiod_get_fd("/dev/gpiochip0", 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO device: %s\n", strerror(errno));
        return 1;
    }

    // Set the GPIO line configuration
    line_config.line_name = "gpio17";
    line_config.direction = GPIDIO_DIRECTION_OUT;
    line_config.edge_detection = GPIDIO_EDGE_FALLING;
    line_config.pull_up_down = GPIDIO_PULL_UP_DOWN_DISABLE;

    // Set the GPIO line state
    gpio_num = 17;
    line_state = gpiod_line_get_level(fd, gpio_num) ? 1 : 0;
    line_config.value = line_state;

    // Apply the GPIO line configuration
    if (gpiod_line_set_config(fd, &line_config) < 0) {
        fprintf(stderr, "Failed to set GPIO line configuration: %s\n", strerror(errno));
        return 1;
    }

    // Print the initial GPIO state
    printf("Initial GPIO state: %d\n", gpiod_line_get_level(fd, gpio_num));

    // Wait for user input to exit
    char input;
    while (1) {
        if (scanf("%c", &input) != 1) {
            fprintf(stderr, "Failed to read user input\n");
            return 1;
        }

        if (input == 'q') {
            break;
        }

        // Apply the new GPIO state
        gpio_num = 17;
        line_state = input % 2;
        line_config.value = line_state;

        if (gpiod_line_set_config(fd, &line_config) < 0) {
            fprintf(stderr, "Failed to set GPIO line configuration: %s\n", strerror(errno));
            return 1;
        }

        // Print the new GPIO state
        printf("GPIO %d state: %d\n", gpio_num, line_state);
    }

    // Release the GPIO file descriptor and hardware resources
    if (gpiod_line_release(fd, gpio_num) < 0) {
        fprintf(stderr, "Failed to release GPIO line: %s\n", strerror(errno));
        return 1;
    }

    return 0;
}

