#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/i2c-gpio.h>

#define VEML7700_ADDRESS 0x10
#define I2C_BUS "/dev/i2c-1"

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg[2];
    int ret;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set up the I2C device file descriptor
    if (ioctl(fd, I2C_SLAVE, VEML7700_ADDRESS) < 0) {
        perror("Failed to set I2C device address");
        exit(EXIT_FAILURE);
    }

    // Initialize the I2C bus
    if (ioctl(fd, I2C_FUNCS, (1 << 6) | (1 << 7)) < 0) {
        perror("Failed to set I2C bus functions");
        exit(EXIT_FAILURE);
    }

    // Set up the I2C message structure
    msg[0].addr = VEML7700_ADDRESS;
    msg[0].flags = 0;
    msg[1].addr = VEML7700_ADDRESS;
    msg[1].flags = 0;
    msg[0].len = 2;
    msg[1].len = 2;
    msg[0].buf = (void *)&data;
    msg[1].buf = (void *)&data;

    // Read data from VEML7700
    ret = i2c_transfer(fd, msg, 2);
    if (ret < 0) {
        perror("Failed to read data from VEML7700");
        exit(EXIT_FAILURE);
    }

    // Print the reading to standard output
    printf("VEML7700 reading: 0x%02x 0x%02x\n", data.data_raw[0], data.data_raw[1]);

    // Repeat the process once every 0.5 seconds
    while (1) {
        usleep(500000); // 0.5 seconds
        ret = i2c_transfer(fd, msg, 2);
        if (ret < 0) {
            perror("Failed to read data from VEML7700");
            exit(EXIT_FAILURE);
        }
    }

    // Release the I2C device file descriptor
    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/termios.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/serial.h>

#define SERIAL_DEVICE "/dev/ttyS0"
#define BAUDRATE 9600
#define TIMEOUT_MS 100

int main() {
    int fd;
    struct termios options;
    struct serial_struct* serial;
    char buffer[256];
    int error;

    fd = open(SERIAL_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("Error opening serial device");
        exit(EXIT_FAILURE);
    }

    // Set serial port parameters
    options.c_cflag = BAUDRATE | CS8 | CLOCAL | CREAD;
    options.c_iflag = IGNPAR;
    options.c_oflag = 0;
    options.c_lflag = 0;

    if (tcgetattr(fd, &options) < 0) {
        perror("Error setting serial port parameters");
        exit(EXIT_FAILURE);
    }

    if (tcsetattr(fd, TCSANOW, &options) < 0) {
        perror("Error setting serial port parameters");
        exit(EXIT_FAILURE);
    }

    // Initialize serial port
    serial = (struct serial_struct*)malloc(sizeof(struct serial_struct));
    if (!serial) {
        perror("Error allocating memory for serial port");
        exit(EXIT_FAILURE);
    }

    serial->fd = fd;
    serial->baudrate = BAUDRATE;
    serial->timeout_ms = TIMEOUT_MS;
    serial->is_open = 0;

    if (ioctl(fd, TIOCMGET, &options) < 0) {
        perror("Error getting serial port control mode");
        exit(EXIT_FAILURE);
    }

    if (!(options.c_cflag & CSTOPB)) {
        options.c_cflag &= ~CSTOPB;
        options.c_cflag |= CS8;
        options.c_cflag &= ~PARENB;
        options.c_cflag &= ~CREAD;
    }

    if (ioctl(fd, TIOCMSET, &options) < 0) {
        perror("Error setting serial port parameters");
        exit(EXIT_FAILURE);
    }

    serial->is_open = 1;

    // Infinite loop to read and print data from the device
    while (1) {
        if (read(fd, buffer, sizeof(buffer)) < 0) {
            perror("Error reading from serial device");
            exit(EXIT_FAILURE);
        }

        printf("Received: %s\n", buffer);

        if (write(fd, buffer, strlen(buffer)) < 0) {
            perror("Error writing to serial device");
            exit(EXIT_FAILURE);
        }

        usleep(TIMEOUT_MS);
    }

    close(fd);
    free(serial);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/gpiod.h>

#define GPIO_SR04_TRIGGER 17
#define GPIO_SR04_ECHO 18

int main() {
    int fd, gpio_direction, gpio_value;
    struct gpiod_event event;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Set the direction of GPIO 17 and 18 to output
    if (gpiod_set_direction(GPIO_SR04_TRIGGER, GPIDIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set direction of GPIO 17 and 18\n");
        gpiod_exit();
        return 1;
    }

    if (gpiod_set_value(GPIO_SR04_TRIGGER, 0) < 0) {
        fprintf(stderr, "Failed to set trigger value of GPIO 17\n");
        gpiod_exit();
        return 1;
    }

    if (gpiod_set_direction(GPIO_SR04_ECHO, GPIDIO_INPUT) < 0) {
        fprintf(stderr, "Failed to set direction of GPIO 18\n");
        gpiod_exit();
        return 1;
    }

    if (gpiod_set_value(GPIO_SR04_ECHO, 0) < 0) {
        fprintf(stderr, "Failed to set echo value of GPIO 18\n");
        gpiod_exit();
        return 1;
    }

    // Loop to read and report the state of the HC-SR04
    while (1) {
        fd = gpiod_event_add(GPIO_SR04_TRIGGER, &event);
        if (fd < 0) {
            fprintf(stderr, "Failed to add event for GPIO 17\n");
            gpiod_exit();
            return 1;
        }

        if (gpiod_event_wait(fd, &event) < 0) {
            fprintf(stderr, "Failed to wait for event on GPIO 17\n");
            gpiod_event_del(fd);
            gpiod_exit();
            return 1;
        }

        if (event.type == GPIDIO_EVENT_GPIO_LEVEL_CHANGE) {
            gpio_value = gpiod_get_value(GPIO_SR04_TRIGGER);
            if (gpio_value == 0) {
                printf("HC-SR04 triggered\n");
            } else {
                printf("HC-SR04 not triggered\n");
            }
        }

        gpiod_event_del(fd);
    }

    gpiod_exit();
    return 0;
}

