#define I2C_DEVICE_ADDRESS 0x53

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    int ret;

    // Open the I2C device file
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Could not open I2C device file\n");
        return 1;
    }

    // Set the I2C address to 0x53
    data.flags = I2C_RDWR;
    data.addr = I2C_ADDR_NONE;
    data.function = I2C_FUNC_I2C;
    data.timeout_ns = 100000;
    data.bytes_to_read = 1;
    data.bytes_to_write = 1;
    data.buf = (void *)&fd;
    data.buf_len = sizeof(fd);

    // Perform the I2C read operation
    ret = ioctl(fd, I2C_RDWR, &data);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to perform I2C read operation\n");
        return 1;
    }

    // Read the data from the ADXL345
    data.flags = I2C_RDWR;
    data.addr = I2C_ADDR_NONE;
    data.function = I2C_FUNC_I2C;
    data.timeout_ns = 100000;
    data.bytes_to_read = 1;
    data.buf = (void *)&fd;
    data.buf_len = sizeof(fd);

    ret = ioctl(fd, I2C_RDWR, &data);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to perform I2C read operation\n");
        return 1;
    }

    // Print the reading to standard output
    printf("Reading from ADXL345: %d\n", fd);

    // Release the I2C device file
    close(fd);

    return 0;
}

