int main() {
    int fd, value;
    struct gpiod_event_attr event_attr;
    struct gpiod_event_info event_info;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open GPIO file descriptors
    fd = gpiod_get_event_file(GPIO_17);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO file descriptor for GPIO 17\n");
        gpiod_exit();
        return 1;
    }

    fd = gpiod_get_event_file(GPIO_18);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO file descriptor for GPIO 18\n");
        gpiod_exit();
        return 1;
    }

    fd = gpiod_get_event_file(GPIO_27);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO file descriptor for GPIO 27\n");
        gpiod_exit();
        return 1;
    }

    // Set up the event attributes
    event_attr.type = GPIGPIO_EVENT_TYPE_LEVEL;
    event_attr.event_flags = GPIGPIO_EVENT_FALLING;
    event_attr.event_value = 0;
    event_attr.event_edge = GPIGPIO_EVENT_EDGE_FALLING;

    // Attach the event to GPIO 17, 18, and 27
    if (gpiod_event_attr_set(fd, GPIO_17, &event_attr) < 0) {
        fprintf(stderr, "Failed to set up event for GPIO 17\n");
        gpiod_exit();
        return 1;
    }
    if (gpiod_event_attr_set(fd, GPIO_18, &event_attr) < 0) {
        fprintf(stderr, "Failed to set up event for GPIO 18\n");
        gpiod_exit();
        return 1;
    }
    if (gpiod_event_attr_set(fd, GPIO_27, &event_attr) < 0) {
        fprintf(stderr, "Failed to set up event for GPIO 27\n");
        gpiod_exit();
        return 1;
    }

    // Wait for the sensor to trigger
    while (1) {
        value = gpiod_get_event_value(fd);
        if (value == 0) {
            printf("Sensor triggered\n");
            break;
        }
    }

    // Release the GPIO file descriptors and close the libgpiod connection
    gpiod_event_attr_unset(fd, GPIO_17);
    gpiod_event_attr_unset(fd, GPIO_18);
    gpiod_event_attr_unset(fd, GPIO_27);
    gpiod_exit();

