    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C address of TCS34725
    if (ioctl(fd, I2C_SLAVE, I2C_DEVICE_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO for TCS34725
    if (gpio_request_from_mem(GPIO_TCS34725_ADDR, 1, &data) < 0) {
        perror("Failed to request GPIO");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C device
    if (i2c_open(fd) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set up I2C communication
    msg[0].addr = I2C_DEVICE_ADDRESS;
    msg[0].flags = 0;
    msg[0].len = 2;
    msg[0].buf = (void *)&data;
    msg[1].addr = I2C_DEVICE_ADDRESS;
    msg[1].flags = 0;
    msg[1].len = 1;
    msg[1].buf = &data;

    // Read data from TCS34725
    data.i2c_msg = msg;
    data.i2c_nmsgs = 2;
    rc = i2c_transfer(fd, &data, 2);
    if (rc < 0) {
        perror("Failed to read data from TCS34725");
        exit(EXIT_FAILURE);
    }

    // Print each reading to standard output
    while (1) {
        printf("TCS34725 reading: %d\n", data.tcs34725_raw);
        usleep(500000); // Repeat every 0.5 seconds
    }

    // Release resources
    i2c_release(fd);
    gpio_release_mem(GPIO_TCS34725_ADDR);
    i2c_close(fd);

    return 0;
}

