        gpiod_release(fd);
        return 1;
    }

    if (gpiod_get_value(fd, gpio_num) < 0) {
        fprintf(stderr, "Failed to get value for GPIO %d: %s\n", gpio_num, strerror(errno));
        gpiod_release(fd);
        return 1;
    }

    // Set GPIO 17 and 24 to output
    state = 1;
    if (gpiod_set_value(fd, gpio_num, state) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to %d: %s\n", gpio_num, state, strerror(errno));
        gpiod_release(fd);
        return 1;
    }

    // Wait for the GPIO to change state
    event.type = GPIGPIO_EVENT_GPIO_EDGE_FALLING;
    event.gpio_num = gpio_num;
    event.event_mask = GPIGPIO_EVENT_GPIO_EDGE_FALLING;
    if (gpiod_event_wait(fd, &event, NULL) < 0) {
        fprintf(stderr, "Failed to wait for GPIO edge: %s\n", strerror(errno));
        gpiod_release(fd);
        return 1;
    }

    // Print the current state of GPIO 17 and 24
    state = gpiod_get_value(fd, gpio_num);
    if (state == 0) {
        printf("GPIO 17 is set to %d\n", state);
    } else {
        printf("GPIO 17 is set to %d\n", state);
    }

    // Release the GPIO device
    gpiod_release(fd);

    return 0;
}

