#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/termios.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/serial.h>

#define SERIAL_DEVICE "/dev/ttyS0"
#define BAUDRATE 9600
#define TIME_BETWEEN_EXCHANGES 0.1

int main() {
    int fd;
    struct termios options;
    struct serial_struct* serial;
    char buffer[256];
    int error;

    // Initialize serial port
    fd = open(SERIAL_DEVICE, O_RDWR | O_NOCTTY);
    if (fd < 0) {
        perror("Error opening serial port");
        exit(EXIT_FAILURE);
    }

    // Set serial port parameters
    options.c_cflag = BAUDRATE | CS8 | CLOCAL | CREAD;
    options.c_iflag = IGNPAR;
    options.c_oflag = 0;
    options.c_lflag = 0;

    if (tcgetattr(fd, &options) < 0) {
        perror("Error setting serial port parameters");
        exit(EXIT_FAILURE);
    }

    if (tcsetattr(fd, TCSANOW, &options) < 0) {
        perror("Error setting serial port parameters");
        exit(EXIT_FAILURE);
    }

    // Initialize serial port
    serial = (struct serial_struct*)malloc(sizeof(struct serial_struct));
    if (!serial) {
        perror("Error allocating memory for serial port");
        exit(EXIT_FAILURE);
    }

    serial->fd = fd;
    serial->baudrate = BAUDRATE;
    serial->is_open = 0;

    // Set up serial port
    if (ioctl(fd, TIOCMGET, &options.c_cflag) < 0) {
        perror("Error getting serial port parameters");
        exit(EXIT_FAILURE);
    }

    if (options.c_cflag & CRTSCTS) {
        options.c_cflag &= ~(CRTSCTS);
        options.c_cflag |= TIOCM_RTS | TIOCM_CTS;
        if (ioctl(fd, TIOCMGET, &options.c_cflag) < 0) {
            perror("Error setting serial port parameters");
            exit(EXIT_FAILURE);
        }
    }

    // Set up serial port
    if (ioctl(fd, TIOCSCTTY, 0) < 0) {
        perror("Error setting serial port as controlling terminal");
        exit(EXIT_FAILURE);
    }

    // Read from the device until interrupted
    while (1) {
        if (read(fd, buffer, sizeof(buffer)) < 0) {
            perror("Error reading from serial port");
            exit(EXIT_FAILURE);
        }

        // Print the received data to standard output
        printf("Received: %s\n", buffer);

        // Write to the device
        if (write(fd, buffer, strlen(buffer)) < 0) {
            perror("Error writing to serial port");
            exit(EXIT_FAILURE);
        }

        // Wait for the next data exchange
        usleep(TIME_BETWEEN_EXCHANGES * 1000);
    }

    // Release resources
    close(fd);
    free(serial);

    return 0;
}

