        gpiod_close(fd);
        return 1;
    }

    // Set GPIO 18, 23, and 24 as outputs
    gpio_num = 18;
    if (gpiod_set_direction(fd, gpio_num, GPIDIO_DIR_OUT) < 0) {
        fprintf(stderr, "Error: Unable to set GPIO %d as output\n", gpio_num);
        gpiod_close(fd);
        return 1;
    }

    // Set the state of GPIO 18, 23, and 24 to 1 (on)
    if (gpiod_set_value(fd, gpio_num, 1) < 0) {
        fprintf(stderr, "Error: Unable to set GPIO %d to 1\n", gpio_num);
        gpiod_close(fd);
        return 1;
    }

    // Repeat the process once every 0.1 seconds
    while (1) {
        // Wait for the next event
        memset(&event, 0, sizeof(event));
        if (gpiod_get_event(fd, &event, sizeof(event)) < 0) {
            fprintf(stderr, "Error: Unable to get next event\n");
            break;
        }

        // Check if the state of GPIO 18, 23, and 24 has changed
        if (event.state != state) {
            fprintf(stdout, "GPIO %d: %d -> %d\n", gpio_num, event.state, state);
            state = event.state;
        }

        // Release the hardware
        if (gpiod_release(fd) < 0) {
            fprintf(stderr, "Error: Unable to release GPIO device\n");
            break;
        }
    }

    // Close the GPIO device
    gpiod_close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#define I2C_ADDR 0x68
#define I2C_SLAVE_ADDR 0x68

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg[2];
    int ret;

    // Open the I2C device file
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device file");
        exit(EXIT_FAILURE);
    }

    // Set the I2C slave address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        exit(EXIT_FAILURE);
    }

    // Initialize the I2C bus
    if (ioctl(fd, I2C_RDWR, I2C_SLAVE_ADDR) < 0) {
        perror("Error initializing I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set up the I2C message structure
    msg[0].addr = I2C_ADDR;
    msg[0].flags = 0;
    msg[1].addr = I2C_SLAVE_ADDR;
    msg[1].flags = 0;
    msg[0].len = 2;
    msg[1].len = 2;
    msg[0].buf = (void *)&data;
    msg[1].buf = (void *)&data;

    // Read data from MPU6050
    ret = i2c_rdwr(fd, msg, 2, NULL);
    if (ret < 0) {
        perror("Error reading data from MPU6050");
        exit(EXIT_FAILURE);
    }

    // Print the reading to standard output
    printf("Reading: 0x%02x 0x%02x\n", data.address, data.data);

    // Repeat the process once every 1 second
    while (1) {
        ret = usleep(1000);
        if (ret < 0) {
            perror("Error sleeping for 1 second");
            exit(EXIT_FAILURE);
        }
    }

    // Release the I2C bus and close the device file
    if (ioctl(fd, I2C_RDWR, I2C_SLAVE_ADDR) < 0) {
        perror("Error releasing I2C bus");
        exit(EXIT_FAILURE);
    }
    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/gpiod.h>

int main() {
    int fd;
    struct gpiod_event event;
    int state;

    // Initialize the GPIO device
    fd = gpiod_get_device("/dev/gpiochip0");
    if (fd < 0) {
        fprintf(stderr, "Failed to get GPIO device: %s\n", strerror(errno));
        return 1;
    }

    // Set the GPIO 17 as an output
    if (gpiod_set_direction(fd, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO direction: %s\n", strerror(errno));
        gpiod_release(fd);
        return 1;
    }

    // Set the initial state of GPIO 17 to 0
    state = 0;
    if (gpiod_set_value(fd, GPIO_LINE(17), state) < 0) {
        fprintf(stderr, "Failed to set GPIO value: %s\n", strerror(errno));
        gpiod_release(fd);
        return 1;
    }

    // Repeat every 0.6 seconds
    while (1) {
        // Get the current state of GPIO 17
        if (gpiod_get_value(fd, GPIO_LINE(17), &state) < 0) {
            fprintf(stderr, "Failed to get GPIO value: %s\n", strerror(errno));
            gpiod_release(fd);
            return 1;
        }

        // Print the current state
        printf("GPIO 17 state: %d\n", state);

        // Wait for 0.6 seconds
        usleep(600000);
    }

    // Release the GPIO device
    gpiod_release(fd);

    return 0;
}
